const RESOURCE_ROOT_DIRECTORY = new URL("../resources/", import.meta.url);
const TEST_STRESS_MATRIX_ENABLED = process.argv.includes("--stress") || process.env.TEST_STRESS === "1";

function createCatalogBackedGameState(overrides = {}) {
    const enemyCatalog = JSON.parse(readFileSync("./resources/characters/ct_enemies_001.json", "utf8"));
    return createInitialGameState({ ...overrides, enemyCatalog });
}

function categorizedResourcePath(requestPath) {
    const normalized = normalizeResourcePath(requestPath);
    if (!normalized || normalized.includes("/")) return normalized;
    if (/^ct_/.test(normalized)) return `characters/${normalized}`;
    if (/^at_atlas_/.test(normalized)) return `atlases/${normalized}`;
    if (/^it_/.test(normalized)) return `items/${normalized}`;
    if (/^level_(?:t\d+|\d+)\.json$/.test(normalized)) return `levels/${normalized}`;
    if (/^music_\d+\.ogg$/.test(normalized) || normalized === "music.json") return `music/${normalized}`;
    if (normalized === "sound-effects.json") return `sfx/${normalized}`;
    if (/^(?:asset-autotagging-config|asset-generation-tags)\.json$/.test(normalized)) return `editor/${normalized}`;
    if (/^level-generator-themes\//.test(normalized)) return normalized.replace(/^level-generator-themes\//, "generator/themes/");
    if (/^level-generator-/.test(normalized)) return `generator/${normalized}`;
    return normalized;
}

function resourceFileUrl(requestPath) {
    return new URL(categorizedResourcePath(requestPath), RESOURCE_ROOT_DIRECTORY);
}

function readResourceJson(requestPath) {
    return JSON.parse(readFileSync(resourceFileUrl(requestPath), "utf8"));
}

function browserResourceUrl(requestPath) {
    return resourceUrl(categorizedResourcePath(requestPath));
}


function distancePointToRect(x, y, rect) {
    const dx = Math.max(rect.x - x, 0, x - (rect.x + rect.w));
    const dy = Math.max(rect.y - y, 0, y - (rect.y + rect.h));
    return Math.hypot(dx, dy);
}

function applyEditorLevelToWorld(state, editorLevel) {
    const wrapper = editorLevel?.level && typeof editorLevel.level === "object" ? editorLevel : null;
    const source = wrapper ? wrapper.level : editorLevel;
    const testStart = source?.testPlayerStart;
    const entities = Array.isArray(source?.entities) ? source.entities : [];
    if (!testStart || entities.some((entity) => entity?.type === "wizard_entry_door" || entity?.kind === "wizard_entry_door")) {
        return applyEditorLevelToWorldCurrent(state, editorLevel);
    }

    const { testPlayerStart: _discardedTestStart, ...currentSource } = source;
    const testDoorId = "__test_entry_door__";
    currentSource.entities = [
        ...entities,
        {
            id: testDoorId,
            type: "wizard_entry_door",
            x: Number(testStart.x) - 180,
            y: Number(testStart.y),
            w: 150,
            h: 190,
            emergeDistance: 180,
            walkDirection: 1
        }
    ];
    const currentLevel = wrapper ? { ...wrapper, level: currentSource } : currentSource;
    const applied = applyEditorLevelToWorldCurrent(state, currentLevel);
    if (!applied) return false;

    state.world.entities = (state.world.entities || []).filter((entity) => entity.id !== testDoorId);
    if (state.world.entityStates) delete state.world.entityStates[testDoorId];
    state.story.portalIntro = null;
    state.player.visible = true;
    state.player.currentTransform.scaleX = 1;
    state.player.currentTransform.scaleY = 1;
    state.player.currentTransform.x = Number(testStart.x) || 0;
    state.player.currentTransform.y = Number(testStart.y) || 0;
    state.player.spawnX = state.player.currentTransform.x;
    state.player.spawnY = state.player.currentTransform.y;
    state.player.vx = 0;
    state.player.vy = 0;
    state.player.onGround = false;
    state.player.wasOnGround = false;
    state.camera.currentTransform.x = state.player.currentTransform.x;
    state.camera.currentTransform.y = state.player.currentTransform.y - 170;
    state.debug.lastEvents = state.debug.lastEvents.filter((event) => event.portalId !== testDoorId);
    snapAllPresentationSubjects(state);
    return true;
}

