function testTimedTextViewportLayout() {
    assert.equal(STORY_READING_CHARACTERS_PER_SECOND, 18, "story reading speed should be calibrated to 18 characters per second");
    const rendererSource = readFileSync("./src/presentation/canvas-renderer.js", "utf8");
    const letterStart = rendererSource.indexOf("    drawLetterOverlay(story, view) {");
    const letterEnd = rendererSource.indexOf("    drawThoughtOverlay(state, story, view) {", letterStart);
    const letterSource = rendererSource.slice(letterStart, letterEnd);
    assert.doesNotMatch(letterSource, /fillText\(story\.letterTitle/, "the letter title band should remain blank while preserving its spacing");
    const centered = computeTimedTextViewportLayout(80, 200, 0, 5, 40);
    assert.equal(centered.centered, true, "short story text should be vertically centered");
    approx(centered.contentOffset, 60, 0.000001, "short story text should receive a centered top offset");
    assert.equal(centered.maxScroll, 0, "short story text should not create a scrollbar");

    const characterCount = 200;
    const duration = STORY_READING_START_DELAY_SECONDS + characterCount / STORY_READING_CHARACTERS_PER_SECOND;
    const starting = computeTimedTextViewportLayout(320, 200, 0, duration, characterCount);
    assert.equal(starting.centered, false, "long story text should use scrolling");
    approx(starting.scrollOffset, 0, 0.000001, "long story text should begin at the top");
    approx(starting.maxScroll, 120, 0.000001, "scroll distance should equal content overflow");
    const expectedStart = STORY_READING_START_DELAY_SECONDS + (characterCount / STORY_READING_CHARACTERS_PER_SECOND) * (100 / 320);
    const expectedEnd = STORY_READING_START_DELAY_SECONDS + (characterCount / STORY_READING_CHARACTERS_PER_SECOND) * (220 / 320);
    approx(starting.scrollStartTime, expectedStart, 0.000001, "scrolling should wait until the reader reaches the middle of the initial viewport");
    approx(starting.scrollEndTime, expectedEnd, 0.000001, "scrolling should finish when the reader reaches the middle of the final viewport");

    const midway = computeTimedTextViewportLayout(320, 200, (expectedStart + expectedEnd) * 0.5, duration, characterCount);
    approx(midway.scrollOffset, 60, 0.000001, "scrolling should advance linearly with estimated reading position");
    const finished = computeTimedTextViewportLayout(320, 200, expectedEnd, duration, characterCount);
    approx(finished.scrollOffset, 120, 0.000001, "long story text should reach the final lines at the final midpoint milestone");
    const held = computeTimedTextViewportLayout(320, 200, duration, duration, characterCount);
    approx(held.scrollOffset, 120, 0.000001, "the final viewport should remain held until the last character is read");
}

function testResponsiveViewportScaling() {
    const phone = computeResponsiveViewportMetrics(390, 844, 2, 600);
    assert.equal(phone.backingWidth, 780, "phone backing width should still match the real canvas pixels");
    approx(phone.cssScale, 0.65, 0.001, "phone CSS scale should fit 600 virtual pixels into 390 CSS pixels");
    approx(phone.virtualWidth, 600, 0.001, "narrow screens should see a 600-unit-wide virtual viewport");
    approx(phone.zoom, 1.3, 0.001, "phone world-to-canvas zoom should include DPR and the responsive scale");

    const desktop = computeResponsiveViewportMetrics(1280, 720, 1.5, 600);
    approx(desktop.cssScale, 1, 0.001, "desktop scale should not shrink");
    approx(desktop.virtualWidth, 1280, 0.001, "wide screens should keep their real CSS width");
    approx(desktop.zoom, 1.5, 0.001, "desktop zoom should remain DPR-only");

    const highResolution = computeResponsiveViewportMetrics(1920, 1080, 2, 600);
    assert.equal(highResolution.backingWidth, 3840, "1080p CSS output keeps its independent high-DPI backing width");
    assert.equal(highResolution.backingHeight, 2160, "1080p CSS output keeps its independent high-DPI backing height");
    approx(highResolution.virtualWidth, 1920, 0.001, "1080p presentation pixels do not leak into browser simulation coordinates");
    approx(highResolution.virtualHeight, 1080, 0.001, "1080p presentation height remains a virtual viewport measurement");
    approx(highResolution.zoom, 2, 0.001, "1080p world-to-backing conversion applies presentation scale exactly once");

    const fullscreen720 = computeFullscreenPresentationMetrics(1280, 720, true);
    approx(fullscreen720.scale, 2 / 3, 0.000001, "720p fullscreen should scale the 1080p reference composition down uniformly");
    approx(fullscreen720.viewportWidth, FULLSCREEN_REFERENCE_WIDTH, 0.000001, "720p fullscreen should retain the reference world width");
    approx(fullscreen720.viewportHeight, FULLSCREEN_REFERENCE_HEIGHT, 0.000001, "720p fullscreen should retain the reference world height");

    const fullscreen4k = computeResponsiveViewportMetrics(3840, 2160, 1, 600, true);
    assert.equal(fullscreen4k.backingWidth, 3840, "4K fullscreen should retain the full physical backing width for art detail");
    assert.equal(fullscreen4k.backingHeight, 2160, "4K fullscreen should retain the full physical backing height for art detail");
    approx(fullscreen4k.virtualWidth, FULLSCREEN_REFERENCE_WIDTH, 0.000001, "4K fullscreen should not reveal more world horizontally");
    approx(fullscreen4k.virtualHeight, FULLSCREEN_REFERENCE_HEIGHT, 0.000001, "4K fullscreen should not reveal more world vertically");
    approx(fullscreen4k.zoom, 2, 0.000001, "4K fullscreen should rasterize the reference composition at double scale");

    const fullscreenUltrawide = computeFullscreenPresentationMetrics(3440, 1440, true);
    approx(fullscreenUltrawide.viewportWidth, FULLSCREEN_REFERENCE_WIDTH, 0.000001, "ultrawide fullscreen should preserve the reference width");
    assert.ok(fullscreenUltrawide.viewportHeight < FULLSCREEN_REFERENCE_HEIGHT, "ultrawide fullscreen should crop vertically rather than reveal more world");
    approx(fullscreenUltrawide.viewportHeight, 1440 / (3440 / 1920), 0.000001, "ultrawide crop should use a uniform crop-to-fill scale");

    const fullscreenPortrait = computeFullscreenPresentationMetrics(1080, 1920, true);
    approx(fullscreenPortrait.viewportHeight, FULLSCREEN_REFERENCE_HEIGHT, 0.000001, "portrait fullscreen should preserve the reference height");
    assert.ok(fullscreenPortrait.viewportWidth < FULLSCREEN_REFERENCE_WIDTH, "portrait fullscreen should crop horizontally rather than reveal more world");

    const windowed4k = computeFullscreenPresentationMetrics(3840, 2160, false);
    assert.equal(windowed4k.referenceActive, false, "windowed presentation should retain the variable viewport contract");
    approx(windowed4k.viewportWidth, 3840, 0.000001, "windowed presentation may expose the full window width");
    approx(windowed4k.viewportHeight, 2160, 0.000001, "windowed presentation may expose the full window height");
}

function testThoughtBubbleTailAndResponsiveTypography() {
    const placement = computeThoughtBubblePlacement({
        speakerX: 420,
        speakerY: 520,
        bubbleWidth: 440,
        bubbleHeight: 278,
        viewportWidth: 1200,
        viewportHeight: 800,
        zoom: 1,
        dpr: 1
    });
    approx(placement.tailX, 420, 0.001, "the bubble tail should point horizontally at Ignatius");
    approx(placement.tailY, 490, 0.001, "the thought-bubble tail should keep a comfortable 30 px gap above Ignatius's head");

    const phone = computeResponsiveViewportMetrics(390, 844, 2, 600);
    const narrowPlacement = computeThoughtBubblePlacement({
        speakerX: 260,
        speakerY: 1180,
        bubbleWidth: 440 * phone.zoom,
        bubbleHeight: 278 * phone.zoom,
        viewportWidth: phone.backingWidth,
        viewportHeight: phone.backingHeight,
        zoom: phone.zoom,
        dpr: phone.dpr
    });
    assert.ok(narrowPlacement.x >= 0 && narrowPlacement.x + 440 * phone.zoom <= phone.backingWidth, "the thought bubble should remain inside a narrow backing canvas");
    const rendererSource = readFileSync(new URL("../src/presentation/canvas-renderer.js", import.meta.url), "utf8");
    assert.match(rendererSource, /const fontScale = view\.zoom \|\| 1;/, "thought typography should inherit the same narrow-screen scale as its bubble");
    assert.match(rendererSource, /fitWrappedText\(thoughtText, textW, bodyHeight/, "thought text should shrink to fit the painted bubble before scrolling");
}




function testPixmapPyramidSelection() {
    const canvases = [];
    const createCanvas = (width, height) => {
        const drawCalls = [];
        const canvas = {
            width,
            height,
            drawCalls,
            getContext: () => ({
                imageSmoothingEnabled: false,
                imageSmoothingQuality: "low",
                clearRect() {},
                drawImage: (...args) => drawCalls.push(args)
            })
        };
        canvases.push(canvas);
        return canvas;
    };
    const source = { width: 330, height: 330 };
    const pyramid = createPixmapPyramid(source, { createCanvas });
    assert.deepEqual(pyramid.levels.map((level) => level.width).slice(0, 5), [330, 165, 83, 42, 21], "pixmap pyramid should halve dimensions with integer-safe rounding");
    const totalPixels = pyramid.levels.reduce((sum, level) => sum + level.width * level.height, 0);
    assert.ok(totalPixels < 330 * 330 * 2, "pixmap pyramid should remain below the promised two-times pixel-memory ceiling");
    assert.equal(choosePixmapLevel(pyramid, 28, 28).width, 83, "selection should keep roughly two source pixels per destination pixel");
    assert.equal(choosePixmapLevel(pyramid, 100, 100).width, 330, "selection should retain the original when the next level undersamples the target");

    const assertSafeSelection = (testPyramid, targetWidth, targetHeight, oversample = 2) => {
        const requiredWidth = targetWidth * oversample;
        const requiredHeight = targetHeight * oversample;
        const eligible = testPyramid.levels.filter((level) => level.width >= requiredWidth && level.height >= requiredHeight);
        const expected = eligible.length ? eligible[eligible.length - 1] : testPyramid.levels[0];
        const actual = choosePixmapLevel(testPyramid, targetWidth, targetHeight, oversample);
        assert.equal(actual, expected, `selection for ${testPyramid.width}x${testPyramid.height} -> ${targetWidth}x${targetHeight} at ${oversample}x should choose the smallest safe level`);
        if (eligible.length) {
            assert.ok(actual.width >= requiredWidth && actual.height >= requiredHeight, "a reduced source must remain at least the requested oversample in both axes");
            const nextIndex = testPyramid.levels.indexOf(actual) + 1;
            const next = testPyramid.levels[nextIndex];
            if (next) {
                assert.ok(next.width < requiredWidth || next.height < requiredHeight, "the next smaller level must be unsafe in at least one axis");
            }
        } else {
            assert.equal(actual, testPyramid.levels[0], "when even the original is below the requested margin, selection must use the largest available source");
        }
    };

    const sourceSizes = [[330, 330], [331, 329], [640, 96], [97, 641], [17, 9], [3, 2]];
    for (const [sourceWidth, sourceHeight] of sourceSizes) {
        const testPyramid = createPixmapPyramid({ width: sourceWidth, height: sourceHeight }, { createCanvas });
        for (let targetWidth = 0.5; targetWidth <= sourceWidth * 1.2; targetWidth *= 1.31) {
            for (let targetHeight = 0.5; targetHeight <= sourceHeight * 1.2; targetHeight *= 1.37) {
                assertSafeSelection(testPyramid, targetWidth, targetHeight, 2);
            }
        }
        for (const oversample of [1, 1.5, 2, 3]) {
            assertSafeSelection(testPyramid, sourceWidth / 7.25, sourceHeight / 5.75, oversample);
        }
    }

    const rendered = [];
    const context = {
        getTransform: () => ({ a: 1, b: 0, c: 0, d: 1 }),
        drawImage: (...args) => rendered.push(args)
    };
    const chosen = drawPixmap(context, pyramid, 10, 20, 28, 28);
    assert.equal(chosen.width, 83, "draw helper should choose the same safe level from destination size");
    assert.equal(rendered[0][5], 10, "draw helper should preserve destination coordinates");
    assert.equal(rendered[0][7], 28, "draw helper should preserve destination dimensions");
}

async function testGenericRuntimeCharacterProject() {
    const jsonByUrl = new Map();
    for (const filename of [
        "ct_char_enemy_001.json",
        "ct_rig_enemy_001.json",
        "ct_atlas_enemy_001.json",
        "ct_anim_enemy_001_idle.json",
        "ct_anim_enemy_001_walk.json",
        "ct_anim_enemy_001_attack.json",
        "ct_anim_enemy_001_hurt.json",
        "ct_anim_enemy_001_death.json"
    ]) {
        jsonByUrl.set(browserResourceUrl(filename), readResourceJson(filename));
    }
    const drawCalls = [];
    const loadingProgress = [];
    const preparedAtlasCache = new Map();
    let imageLoadCount = 0;
    const loadImage = async (url) => {
        imageLoadCount += 1;
        return { width: 1536, height: 1152, naturalWidth: 1536, naturalHeight: 1152, url };
    };
    const createCanvas = (width, height) => ({
        width,
        height,
        getContext: () => ({
            drawImage: (...args) => drawCalls.push(args)
        })
    });
    const loadJson = async (url) => {
        assert.ok(jsonByUrl.has(url), `runtime loader should resolve known project URL ${url}`);
        return JSON.parse(JSON.stringify(jsonByUrl.get(url)));
    };
    const project = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_001.json", {
        onProgress: (entry) => loadingProgress.push(entry),
        loadJson,
        loadImage,
        createCanvas,
        preparedAtlasCache
    });

    assert.equal(project.characterId, "ct_char_enemy_001", "runtime loader should retain the character ID");
    assert.ok(loadingProgress.length >= 5, "runtime character loading should report meaningful intermediate progress");
    assert.equal(loadingProgress.at(-1).progress, 1, "runtime character loading should finish at 100 percent");
    assert.ok(loadingProgress.every((entry, index) => index === 0 || entry.progress >= loadingProgress[index - 1].progress), "runtime character loading progress should never move backwards");
    assert.equal(project.rig.drawOrder.length, 8, "generic runtime rig should preserve every enemy part");
    assert.equal(project.animations.size, 5, "runtime loader should load all mapped enemy animations");
    assert.deepEqual(project.sounds, { hurt: "sfx/enemy_damage.wav", death: "sfx/enemy_death.wav" }, "runtime loader should preserve character-owned combat WAV references");
    assert.equal(drawCalls.filter((args) => args[0]?.url).length, 9, "runtime loader should crop the eight guard parts plus the shared undeath projectile frame");
    assert.equal(imageLoadCount, 1, "the first runtime character load should decode its atlas once");
    const sourceCropCount = drawCalls.filter((args) => args[0]?.url).length;
    const repeatedProject = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_001.json", {
        loadJson,
        loadImage,
        createCanvas,
        preparedAtlasCache
    });
    assert.equal(imageLoadCount, 1, "a shared prepared-atlas cache should avoid decoding the same character atlas twice");
    assert.equal(drawCalls.filter((args) => args[0]?.url).length, sourceCropCount, "a shared prepared-atlas cache should reuse frame canvases and pixmap pyramids instead of cropping the atlas again");
    assert.notEqual(repeatedProject.atlasAssets, project.atlasAssets, "projects should retain independent atlas-asset maps so releasing one project cannot clear another");
    assert.equal(repeatedProject.atlasAssets.get("head")?.canvas, project.atlasAssets.get("head")?.canvas, "projects sharing an atlas should share immutable prepared frame canvases");
    assert.ok(project.assets.get("head")?.pixmapPyramid?.levels?.length > 1, "runtime character parts should prepare reusable reduced pixmaps while loading");
    assert.equal(resolveRuntimeAnimationSlot(project, "attack"), "attack", "requested mapped animation should resolve directly");
    assert.equal(resolveRuntimeAnimationSlot(project, "missing"), "idle", "missing slots should fall back to idle");

    const sampled = sampleRuntimeCharacterPose(project, "walk", 0.2);
    assert.equal(sampled.slot, "walk", "runtime character sampler should use the requested walk slot");
    const transforms = animationPoseToRuntimeTransforms(sampled.pose, project.rig, 2, 0.75);
    const commands = buildRuntimeCharacterDrawCommands(project, transforms);
    assert.deepEqual(commands.map((command) => command.partName), project.rig.drawOrder, "draw commands should follow rig draw order");
    assert.ok(commands.every((command) => Number.isFinite(command.spriteScale) && command.spriteScale > 0), "draw commands should have finite positive scales");

    const humanRaiderRig = normalizeRuntimeCharacterRig(JSON.parse(readFileSync("./resources/characters/ct_rig_enemy_030.json", "utf8")));
    const humanRaiderAtlas = JSON.parse(readFileSync("./resources/characters/ct_atlas_enemy_030.json", "utf8"));
    const humanRaiderIdle = normalizeAnimationClip(JSON.parse(readFileSync("./resources/characters/ct_anim_enemy_030_idle.json", "utf8")));
    const humanRaiderAssets = new Map(humanRaiderRig.drawOrder.map((partName) => {
        const part = humanRaiderRig.parts[partName];
        const frame = humanRaiderAtlas.frames[part.frame];
        assert.ok(frame, `enemy_030 atlas should contain frame ${part.frame}`);
        return [partName, {
            frameId: part.frame,
            width: frame.w,
            height: frame.h,
            missing: false
        }];
    }));
    const leftUpperArmConstraint = parentConstraintForRuntimePart(humanRaiderRig, "leftUpperArm");
    assert.deepEqual(
        leftUpperArmConstraint,
        {
            parentPart: "torso",
            parentPoint: {
                x: 0.6569620785033716,
                y: 0.20864837588872165
            }
        },
        "enemy_030 leftUpperArm parentConstraint should survive runtime rig normalization"
    );
    const humanRaiderPose = sampleAnimationClip(humanRaiderIdle, 0);
    const humanRaiderTransforms = animationPoseToRuntimeTransforms(humanRaiderPose, humanRaiderRig, 1, 1);
    const expectedLeftShoulder = runtimeParentAttachmentPoint(
        humanRaiderRig,
        "torso",
        leftUpperArmConstraint.parentPoint,
        humanRaiderTransforms.torso,
        humanRaiderAssets
    );
    const resolvedHumanRaiderTransforms = resolveRuntimeParentConstrainedTransforms(humanRaiderRig, humanRaiderTransforms, humanRaiderAssets);
    approx(resolvedHumanRaiderTransforms.leftUpperArm.x, expectedLeftShoulder.x, 0.000001, "enemy_030 leftUpperArm runtime X should attach to the torso shoulder point");
    approx(resolvedHumanRaiderTransforms.leftUpperArm.y, expectedLeftShoulder.y, 0.000001, "enemy_030 leftUpperArm runtime Y should attach to the torso shoulder point");
    approx(resolvedHumanRaiderTransforms.leftUpperArm.angle, humanRaiderTransforms.leftUpperArm.angle, 0.000001, "enemy_030 leftUpperArm rotation should remain independently animated");
    approx(resolvedHumanRaiderTransforms.leftUpperArm.targetHeight, humanRaiderTransforms.leftUpperArm.targetHeight, 0.000001, "enemy_030 leftUpperArm target height should remain independently animated");
    const humanRaiderCommands = buildRuntimeCharacterDrawCommands(
        { rig: humanRaiderRig, assets: humanRaiderAssets },
        humanRaiderTransforms
    );
    const leftUpperArmCommand = humanRaiderCommands.find((command) => command.partName === "leftUpperArm");
    assert.ok(leftUpperArmCommand, "enemy_030 draw commands should include leftUpperArm");
    approx(leftUpperArmCommand.transform.x, expectedLeftShoulder.x, 0.000001, "enemy_030 leftUpperArm draw pivot should land on the torso shoulder X");
    approx(leftUpperArmCommand.transform.y, expectedLeftShoulder.y, 0.000001, "enemy_030 leftUpperArm draw pivot should land on the torso shoulder Y");

    const arbitraryRig = normalizeRuntimeCharacterRig({
        rigId: "tiny",
        drawOrder: ["wing", "body"],
        global: { scale: 1 },
        pivots: { wing: { x: 0.1, y: 0.2 } },
        parts: {
            body: { frame: "body", offset: { x: 3, y: 4 }, targetHeight: 20 },
            wing: { frame: "wing", offset: { x: -2, y: 1 }, targetHeight: 10 }
        }
    });
    assert.deepEqual(arbitraryRig.drawOrder, ["wing", "body"], "generic rigs must not assume wizard or humanoid part names");
    const setupPose = createRuntimeCharacterSetupPose(arbitraryRig);
    assert.equal(setupPose.wing.x, -2, "setup pose should use rig offsets");
    assert.equal(arbitraryRig.pivots.body.x, 0.5, "missing pivots should receive a safe frame-centre default");

    const state = createInitialGameState();
    const level = {
        levelId: "runtime_character_test",
        testPlayerStart: { x: 0, y: 600 },
        entities: [{
            id: "skeleton_runtime_001",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 400,
            y: 600,
            w: 72,
            h: 150,
            facing: -1,
            animationSlot: "idle",
            renderScale: 0.8
        }]
    };
    assert.equal(applyEditorLevelToWorld(state, level), true, "runtime character level entity should apply");
    const enemy = state.enemies.find((item) => item.id === "skeleton_runtime_001");
    assert.ok(enemy, "character enemy should enter simulation presentation state");
    assert.equal(enemy.characterId, "ct_char_enemy_001", "character enemy should retain its project ID");
    assert.equal(enemy.facing, -1, "character enemy should retain authored facing");
    assert.equal(enemy.animationSlot, "idle", "character enemy should retain authored animation slot");
    assert.equal(enemy.maxHealth, 90, "character enemy without authored health should use the serializable 90 HP default");
    assert.equal(enemy.combatState, "alive", "fresh character enemy should begin alive");
}

async function testGoblinRuntimeCharacterProjects() {
    const jsonByUrl = new Map();
    for (const filename of [
        "ct_char_enemy_010.json",
        "ct_char_enemy_011.json",
        "ct_char_enemy_012.json",
        "ct_rig_enemy_010.json",
        "ct_rig_enemy_011.json",
        "ct_rig_enemy_012.json",
        "ct_atlas_enemy_010.json",
        "ct_anim_enemy_010_idle.json",
        "ct_anim_enemy_010_walk.json",
        "ct_anim_enemy_010_attack.json",
        "ct_anim_enemy_010_hurt.json",
        "ct_anim_enemy_010_death.json",
        "ct_anim_enemy_011_idle.json",
        "ct_anim_enemy_011_walk.json",
        "ct_anim_enemy_011_attack.json",
        "ct_anim_enemy_011_hurt.json",
        "ct_anim_enemy_011_death.json",
        "ct_anim_enemy_012_idle.json",
        "ct_anim_enemy_012_walk.json",
        "ct_anim_enemy_012_attack.json",
        "ct_anim_enemy_012_hurt.json",
        "ct_anim_enemy_012_death.json"
    ]) {
        jsonByUrl.set(browserResourceUrl(filename), readResourceJson(filename));
    }
    const preparedAtlasCache = new Map();
    let goblinAtlasImageLoads = 0;
    const loader = {
        loadJson: async (url) => {
            assert.ok(jsonByUrl.has(url), `goblin runtime loader should resolve ${url}`);
            return JSON.parse(JSON.stringify(jsonByUrl.get(url)));
        },
        loadImage: async (url) => {
            goblinAtlasImageLoads += 1;
            return { width: 1371, height: 979, naturalWidth: 1371, naturalHeight: 979, url };
        },
        createCanvas: (width, height) => ({
            width,
            height,
            getContext: () => ({ drawImage: () => {} })
        }),
        preparedAtlasCache
    };

    const fireball = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_010.json", loader);
    const musket = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_011.json", loader);
    const triFireball = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_012.json", loader);
    assert.equal(goblinAtlasImageLoads, 1, "different character projects sharing one atlas should decode that atlas only once when loaded through a shared prepared cache");
    const sharedGoblinFrame = [...fireball.atlasAssets.keys()].find((frameId) => musket.atlasAssets.has(frameId) && triFireball.atlasAssets.has(frameId));
    assert.ok(sharedGoblinFrame, "the three goblin projects should expose at least one common atlas frame");
    assert.equal(fireball.atlasAssets.get(sharedGoblinFrame)?.canvas, musket.atlasAssets.get(sharedGoblinFrame)?.canvas, "different character projects sharing an atlas should reuse the same prepared frame canvas");
    assert.equal(fireball.atlasAssets.get(sharedGoblinFrame)?.pixmapPyramid, triFireball.atlasAssets.get(sharedGoblinFrame)?.pixmapPyramid, "different character projects sharing an atlas should reuse the same pixmap pyramid");

    assert.equal(fireball.characterId, "ct_char_enemy_010", "fireball goblin should keep its character ID");
    assert.equal(musket.characterId, "ct_char_enemy_011", "musket goblin should keep its character ID");
    assert.equal(triFireball.characterId, "ct_char_enemy_012", "tri-fireball goblin should keep its character ID");
    assert.equal(fireball.rig.rigId, "ct_rig_enemy_010", "Fireball Goblin should load its dedicated rig");
    assert.equal(musket.rig.rigId, "ct_rig_enemy_011", "Musket Goblin should load its dedicated rig");
    assert.equal(triFireball.rig.rigId, "ct_rig_enemy_012", "Tri-fireball Goblin should load its copied dedicated rig");
    assert.equal(fireball.rig.parts.leftArm.frame, "leftArmOpen", "Fireball Goblin rig should retain the open casting arm part");
    assert.equal(musket.rig.parts.leftArmClosed.frame, "leftArmClosed", "Musket Goblin rig should retain the closed support arm part");
    assert.equal(musket.rig.parts.rightArm.frame, "rightArmClosed", "Musket Goblin should use the corrected closed right trigger arm");
    assert.equal(musket.rig.parts.weapon.frame, "musket", "Musket Goblin should use the musket frame");
    assert.deepEqual(fireball.rig.pivots.rightArm, { x: 0.18, y: 0.31 }, "Enemy 010 right-arm pivot should come directly from its rig");
    assert.deepEqual(musket.rig.pivots.rightArm, { x: 0.17, y: 0.29 }, "Enemy 011 right-arm pivot should come directly from its rig without character-level replacement");
    assert.deepEqual(
        fireball.rig.drawOrder,
        jsonByUrl.get("resources/characters/ct_rig_enemy_010.json").drawOrder,
        "runtime goblin rig should preserve the user-authored depth-first order"
    );
    assert.equal(fireball.atlasAssets.get("fireball")?.frameId, "fireball", "runtime project should expose the authored fireball atlas resource");
    assert.equal(musket.atlasAssets.get("cannonball")?.frameId, "cannonball", "runtime project should expose unattached cannonball atlas resources");
    assert.equal(fireball.animations.size, 5, "fireball goblin should resolve its dedicated animation set");
    assert.equal(musket.animations.size, 5, "musket goblin should resolve its dedicated weapon-aware animation set");
    assert.equal(triFireball.animations.size, 5, "tri-fireball goblin should resolve its copied Fireball Goblin animation set");
    assert.equal(fireball.projectiles.size, 1, "Fireball Goblin should activate only its selected projectile part");
    assert.equal(musket.projectiles.size, 1, "Musket Goblin should activate only its selected projectile part");
    assert.equal(triFireball.projectiles.size, 1, "Tri-fireball Goblin should activate only its copied fireball projectile part");
    const fireballProjectile = fireball.projectiles.get("fireball");
    const musketProjectile = musket.projectiles.get("cannonball");
    const triFireballProjectile = triFireball.projectiles.get("fireball");
    const enemyCatalog = JSON.parse(readFileSync("./resources/characters/ct_enemies_001.json", "utf8"));
    assert.equal(enemyCatalog.enemies.enemy_010.defaults.projectileLaunchType, "homing_lo", "Fireball Goblin low-homing trajectory should come from the catalog, not the rig handoff");
    assert.equal(fireballProjectile.animationSlot, "attack", "fireball handoff should be attached to the attack slot");
    approx(fireballProjectile.releaseTime, 0.372, 0.000001, "fireball handoff should use the explicit authored release time");
    assert.ok(fireballProjectile.localX > 200 && fireballProjectile.localY < -180, "fireball release should sample the ground-normalized authored attack position");
    assert.equal(enemyCatalog.enemies.enemy_012.defaults.projectileLaunchType, "straight", "Tri-fireball Goblin straight trajectory should come from the catalog independently of its copied handoff");
    approx(triFireballProjectile.releaseTime, fireballProjectile.releaseTime, 0.000001, "Tri-fireball Goblin should copy the Fireball Goblin release timing");
    assert.equal(enemyCatalog.enemies.enemy_011.defaults.projectileLaunchType, "ballistic", "Musket Goblin ballistic trajectory should come from the catalog, not the rig handoff");
    approx(musketProjectile.releaseTime, 0.49531814840382643, 0.000001, "cannonball handoff should use the explicit authored release time");
    assert.ok(musketProjectile.localX > 180 && musketProjectile.localY < -220, "cannonball release should sample the ground-normalized muzzle position");
    const beforeRelease = sampleRuntimeCharacterPose(fireball, "attack", 0.35);
    const beforeTransforms = animationPoseToRuntimeTransforms(beforeRelease.pose, fireball.rig, 1, 1);
    assert.equal(applyRuntimeProjectileHandoffVisibility(fireball, "attack", 0.35, beforeTransforms), 0, "projectile rig part should remain visible before handoff");
    const released = sampleRuntimeCharacterPose(fireball, "attack", fireballProjectile.releaseTime);
    const releasedTransforms = animationPoseToRuntimeTransforms(released.pose, fireball.rig, 1, 1);
    assert.equal(applyRuntimeProjectileHandoffVisibility(fireball, "attack", fireballProjectile.releaseTime, releasedTransforms), 1, "projectile rig part should be hidden at handoff");
    assert.equal(releasedTransforms.fireball.alpha, 0, "released fireball should no longer remain attached to the character pose");
}

async function testBatFrameSwapProjectsAndFlight() {
    const retainedSuffixes = ["020"];
    const jsonByUrl = new Map();
    for (const suffix of retainedSuffixes) {
        for (const filename of [
            `ct_char_enemy_${suffix}.json`,
            `ct_rig_enemy_${suffix}.json`,
            `ct_atlas_enemy_${suffix}.json`,
            `ct_anim_enemy_${suffix}_fly.json`
        ]) {
            jsonByUrl.set(browserResourceUrl(filename), readResourceJson(filename));
        }
    }
    for (const filename of [
        "ct_char_enemy_021.json",
        "ct_rig_enemy_021.json"
    ]) {
        jsonByUrl.set(browserResourceUrl(filename), readResourceJson(filename));
    }
    const loader = {
        loadJson: async (url) => {
            assert.ok(jsonByUrl.has(url), `bat runtime loader should resolve ${url}`);
            return JSON.parse(JSON.stringify(jsonByUrl.get(url)));
        },
        loadImage: async (url) => ({ width: 2047, height: 1078, naturalWidth: 2047, naturalHeight: 1078, url }),
        createCanvas: (width, height) => ({
            width,
            height,
            getContext: () => ({ drawImage: () => {} })
        })
    };

    for (const suffix of retainedSuffixes) {
        const project = await loadRuntimeCharacterProject(`resources/characters/ct_char_enemy_${suffix}.json`, loader);
        assert.equal(project.characterId, `ct_char_enemy_${suffix}`, `retained bat ${suffix} should keep its numbered character ID`);
        assert.equal(project.animations.size, 1, `retained bat ${suffix} should use one deliberately minimal fly clip`);
        assert.ok(project.rig.drawOrder.length >= 16, `retained bat ${suffix} should stack its atlas frames as ordinary rig parts`);
        for (const sampleTime of [0.01, 0.21, 0.43, 0.67]) {
            const sampled = sampleRuntimeCharacterPose(project, "fly", sampleTime);
            const visibleParts = Object.values(sampled.pose).filter((transform) => Number(transform.alpha) > 0.5);
            assert.equal(visibleParts.length, 1, `retained bat ${suffix} should show exactly one atlas frame at ${sampleTime}s`);
        }
    }

    const enemyCatalog = readResourceJson("ct_enemies_001.json");
    assert.equal(enemyCatalog.enemies.enemy_020.defaults.corpseFadeDuration, 3, "red bombing bat should use the standard three-second defeated-enemy fade");
    assert.equal(enemyCatalog.enemies.enemy_021.defaults.corpseFadeDuration, 3, "blue bombing bat should use the standard three-second defeated-enemy fade");

    const atlas020 = jsonByUrl.get("resources/characters/ct_atlas_enemy_020.json");
    const rig020 = jsonByUrl.get("resources/characters/ct_rig_enemy_020.json");
    const animation020 = jsonByUrl.get("resources/characters/ct_anim_enemy_020_fly.json");
    const orderedFrameNames = Array.from({ length: 22 }, (_, index) => `frame_${String(index + 1).padStart(2, "0")}`);
    assert.deepEqual(Object.keys(atlas020.frames).slice(0, 22), orderedFrameNames, "Atlas 020 should expose all 22 animation frames in authored order");
    assert.deepEqual([atlas020.frames.rock.w, atlas020.frames.rock.h], [60, 56], "Atlas 020 should preserve the supplied rock projectile frame dimensions after atlas reforging");
    assert.deepEqual(rig020.drawOrder, orderedFrameNames, "replacement Atlas 020 rig should preserve source order exactly");
    assert.equal(animation020.duration, 1.1, "22 Atlas 020 frames should play at 20 FPS");
    assert.equal(Object.keys(animation020.tracks).length, 22, "replacement Atlas 020 should key every supplied frame");
    assert.equal(animation020.presentation?.mode, "exclusive_frame_parts", "frame-swapped bat should declare its animation presentation contract");
    assert.deepEqual(animation020.presentation?.parts, orderedFrameNames, "frame-swapped bat should declare every exclusive frame part in source order");

    const project020 = await loadRuntimeCharacterProject("resources/characters/ct_char_enemy_020.json", loader);
    assert.equal(project020.animations.get("fly").presentation.mode, "exclusive_frame_parts", "runtime should retain the validated frame-sequence contract");
    for (let index = 0; index < orderedFrameNames.length; index += 1) {
        const sampled = sampleRuntimeCharacterPose(project020, "fly", index * 0.05 + 0.001);
        const visibleNames = Object.entries(sampled.pose)
            .filter(([, transform]) => Number(transform.alpha) > 0.5)
            .map(([partName]) => partName);
        assert.deepEqual(visibleNames, [orderedFrameNames[index]], `Atlas 020 sample ${index + 1} should select its matching source frame`);
    }
    const state = createInitialGameState();
    applyEditorLevelToWorld(state, {
        levelId: "bat_flight_test",
        testPlayerStart: { x: 100, y: 600 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 10000 } },
        entities: [{
            id: "bat_candidate_test",
            type: "characterEnemy",
            characterId: "ct_char_enemy_020",
            x: 520,
            y: 280,
            w: 84,
            h: 66,
            facing: -1,
            strategy: "simple_patrol",
            locomotion: "flying",
            patrolDistance: 420,
            walkSpeed: 105,
            flightAmplitude: 16,
            flightCyclesPerSecond: 0.58,
            deathFlightSpeed: 520,
            deathFlightLift: 210,
            deathFlightGravity: 90,
            deathFlyOffDistance: 720,
            corpseFadeDuration: 1,
            health: 1,
            animationSlot: "fly",
            loopAnimationPhaseVariation: 0.2,
            loopAnimationPeriodVariation: 0.2
        }]
    });
    const bat = state.enemies.find((enemy) => enemy.id === "bat_candidate_test");
    assert.ok(bat, "flying bat should enter portable simulation state");
    assert.equal(bat.locomotion, "flying", "bat should retain its flying locomotion mode");
    assert.ok(bat.loopAnimationPhaseOffsetCycles >= -0.2 && bat.loopAnimationPhaseOffsetCycles <= 0.2, "bat flap starting phase should stay inside the authored +/-20% range");
    assert.ok(bat.loopAnimationPeriodScale >= 0.8 && bat.loopAnimationPeriodScale <= 1.2, "bat flap period should stay inside the authored +/-20% range");
    const replayState = createInitialGameState();
    applyEditorLevelToWorld(replayState, {
        levelId: "bat_flight_test",
        testPlayerStart: { x: 100, y: 600 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 10000 } },
        entities: [{
            id: "bat_candidate_test",
            type: "characterEnemy",
            characterId: "ct_char_enemy_020",
            x: 520,
            y: 280,
            locomotion: "flying",
            health: 1,
            animationSlot: "fly",
            loopAnimationPhaseVariation: 0.2,
            loopAnimationPeriodVariation: 0.2
        }]
    });
    const replayBat = replayState.enemies.find((enemy) => enemy.id === "bat_candidate_test");
    assert.equal(replayBat.loopAnimationPhaseOffsetCycles, bat.loopAnimationPhaseOffsetCycles, "the same bat identity should reproduce its deterministic flap phase");
    assert.equal(replayBat.loopAnimationPeriodScale, bat.loopAnimationPeriodScale, "the same bat identity should reproduce its deterministic flap period");
    const secondState = createInitialGameState();
    applyEditorLevelToWorld(secondState, {
        levelId: "bat_flight_test",
        testPlayerStart: { x: 100, y: 600 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 10000 } },
        entities: [{
            id: "bat_candidate_test_2",
            type: "characterEnemy",
            characterId: "ct_char_enemy_020",
            x: 560,
            y: 280,
            locomotion: "flying",
            health: 1,
            animationSlot: "fly",
            loopAnimationPhaseVariation: 0.2,
            loopAnimationPeriodVariation: 0.2
        }]
    });
    const secondBat = secondState.enemies.find((enemy) => enemy.id === "bat_candidate_test_2");
    assert.ok(
        secondBat.loopAnimationPhaseOffsetCycles !== bat.loopAnimationPhaseOffsetCycles || secondBat.loopAnimationPeriodScale !== bat.loopAnimationPeriodScale,
        "different bat identities should not be forced into the same flap phase and period"
    );
    const variedFlyTime = runtimeLoopVariantAnimationTime(project020, "fly", 1.1, 0.2, 1.2);
    assert.ok(Math.abs(variedFlyTime - (1.1 / 1.2 + 0.22)) < 0.000001, "fly sampling should divide by period scale and add phase cycles in clip-duration units");
    assert.equal(runtimeLoopVariantAnimationTime(project020, "hurt", 1.1, 0.2, 1.2), 1.1, "non-fly animation slots should ignore loop phase and period variation");
    const startX = bat.currentTransform.x;
    const startY = bat.currentTransform.y;
    for (let step = 0; step < 60; step += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    assert.ok(bat.currentTransform.x < startX - 80, "living bat should patrol horizontally through open air");
    assert.ok(Math.abs(bat.currentTransform.y - startY) > 2, "living bat should bob around its authored flight height");
    assert.equal(bat.animationSlot, "fly", "living bat should keep the frame-swapped fly loop selected");
    assert.equal(bat.supportId, null, "flying bat should never acquire a ground support");

    const blockedFlightState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(blockedFlightState, {
        levelId: "bat_blockable_flight_test",
        testPlayerStart: { x: 100, y: 600 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 1000 } },
        entities: [{
            id: "blocked_bat_candidate", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 520, y: 280, w: 84, h: 66, facing: -1, strategy: "simple_patrol", locomotion: "flying",
            patrolDistance: 420, walkSpeed: 105, flightAmplitude: 16, flightCyclesPerSecond: 0.58,
            health: 1, animationSlot: "fly"
        }, {
            id: "blocked_bomber_candidate", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 520, y: 380, w: 84, h: 66, facing: -1, strategy: "bomber", locomotion: "flying",
            patrolDistance: 420, walkSpeed: 105, bomberHorizontalSpeed: 105, awarenessRange: 0,
            flightAmplitude: 16, flightCyclesPerSecond: 0.58, health: 1, animationSlot: "fly"
        }]
    }), true, "flying blockable-collision regression level should apply");
    blockedFlightState.story.portalIntro = null;
    blockedFlightState.story.portalExit = null;
    blockedFlightState.world.segments.push({
        id: "bat_blocking_wall", kind: "blockable", x1: 450, y1: 120, x2: 450, y2: 420
    });
    const blockedBat = blockedFlightState.enemies.find((enemy) => enemy.id === "blocked_bat_candidate");
    let minimumBlockedBatX = blockedBat.currentTransform.x;
    for (let step = 0; step < 90; step += 1) {
        stepSimulation(blockedFlightState, createInputFrame(), FIXED_DT);
        minimumBlockedBatX = Math.min(minimumBlockedBatX, blockedBat.currentTransform.x);
    }
    assert.ok(minimumBlockedBatX >= 491.9,
        `ordinary flying patrol should be obstructed by a vertical blockable wall; min x=${minimumBlockedBatX}`);
    assert.ok(blockedBat.health > 0 && blockedBat.combatState !== "dead",
        "a flying enemy should turn away from blockable geometry instead of entering it and relying on defensive telefragging");
    assert.equal(blockedBat.supportId, null, "blockable obstruction must not turn flying locomotion into grounded support");
    const blockedBomber = blockedFlightState.enemies.find((enemy) => enemy.id === "blocked_bomber_candidate");
    let minimumBlockedBomberX = blockedBomber.currentTransform.x;
    for (let step = 0; step < 90; step += 1) {
        stepSimulation(blockedFlightState, createInputFrame(), FIXED_DT);
        minimumBlockedBomberX = Math.min(minimumBlockedBomberX, blockedBomber.currentTransform.x);
    }
    assert.ok(minimumBlockedBomberX >= 491.9,
        `inactive bomber patrol should also be obstructed by blockable geometry; min x=${minimumBlockedBomberX}`);
    assert.ok(blockedBomber.health > 0 && blockedBomber.combatState !== "dead",
        "inactive bomber should turn at blockable geometry rather than entering it and relying on telefragging");

    const shallowFlightState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(shallowFlightState, {
        levelId: "bat_shallow_blockable_flight_test",
        testPlayerStart: { x: 100, y: 700 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 1000 } },
        entities: [{
            id: "shallow_blocked_bat", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 700, y: 320, w: 84, h: 66, facing: -1, strategy: "simple_patrol", locomotion: "flying",
            patrolDistance: 700, walkSpeed: 105, flightAmplitude: 0, flightCyclesPerSecond: 0.58,
            health: 1, animationSlot: "fly"
        }]
    }), true, "shallow flying blockable-collision regression level should apply");
    shallowFlightState.story.portalIntro = null;
    shallowFlightState.story.portalExit = null;
    shallowFlightState.world.segments.push({
        id: "bat_shallow_blocking_slope", kind: "blockable", x1: 400, y1: 200, x2: 650, y2: 350
    });
    const shallowBlockedBat = shallowFlightState.enemies.find((enemy) => enemy.id === "shallow_blocked_bat");
    let minimumShallowBlockedBatX = shallowBlockedBat.currentTransform.x;
    for (let step = 0; step < 120; step += 1) {
        stepSimulation(shallowFlightState, createInputFrame(), FIXED_DT);
        minimumShallowBlockedBatX = Math.min(minimumShallowBlockedBatX, shallowBlockedBat.currentTransform.x);
    }
    assert.ok(minimumShallowBlockedBatX >= 620,
        `flying patrol should be obstructed by shallow blockable lines too; min x=${minimumShallowBlockedBatX}`);
    assert.ok(shallowBlockedBat.health > 0 && shallowBlockedBat.combatState !== "dead",
        "shallow blockable obstruction should turn a flyer rather than allowing it through or killing it");
    assert.equal(shallowBlockedBat.supportId, null, "shallow blockable obstruction must not ground flying locomotion");

    const horizontalFlightState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(horizontalFlightState, {
        levelId: "bat_horizontal_blockable_flight_test",
        testPlayerStart: { x: 100, y: 700 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 1000 } },
        entities: [{
            id: "horizontal_blocked_bat", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 700, y: 320, w: 84, h: 66, facing: -1, strategy: "simple_patrol", locomotion: "flying",
            patrolDistance: 700, walkSpeed: 105, flightAmplitude: 0, flightCyclesPerSecond: 0.58,
            health: 1, animationSlot: "fly"
        }]
    }), true, "horizontal flying blockable-collision regression level should apply");
    horizontalFlightState.story.portalIntro = null;
    horizontalFlightState.story.portalExit = null;
    horizontalFlightState.world.segments.push({
        id: "bat_horizontal_blocking_line", kind: "blockable", x1: 400, y1: 290, x2: 650, y2: 290
    });
    const horizontalBlockedBat = horizontalFlightState.enemies.find((enemy) => enemy.id === "horizontal_blocked_bat");
    let minimumHorizontalBlockedBatX = horizontalBlockedBat.currentTransform.x;
    for (let step = 0; step < 120; step += 1) {
        stepSimulation(horizontalFlightState, createInputFrame(), FIXED_DT);
        minimumHorizontalBlockedBatX = Math.min(minimumHorizontalBlockedBatX, horizontalBlockedBat.currentTransform.x);
    }
    assert.ok(minimumHorizontalBlockedBatX >= 690,
        `flying patrol should be obstructed by horizontal blockable lines crossing its body; min x=${minimumHorizontalBlockedBatX}`);
    assert.ok(horizontalBlockedBat.health > 0 && horizontalBlockedBat.combatState !== "dead",
        "horizontal blockable-line obstruction should turn the flyer instead of letting it pass through");
    assert.equal(horizontalBlockedBat.supportId, null, "horizontal blockable-line obstruction must not ground flying locomotion");

    const descendingFlightState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(descendingFlightState, {
        levelId: "bat_descending_steep_blockable_flight_test",
        testPlayerStart: { x: 100, y: 700 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 1000 } },
        entities: [{
            id: "descending_blocked_bat", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 700, y: 280, w: 84, h: 66, facing: 1, strategy: "simple_patrol", locomotion: "flying",
            patrolDistance: 0, walkSpeed: 0, flightAmplitude: 100, flightCyclesPerSecond: 1,
            health: 1, animationSlot: "fly"
        }]
    }), true, "descending flyer blockable-collision regression level should apply");
    descendingFlightState.story.portalIntro = null;
    descendingFlightState.story.portalExit = null;
    descendingFlightState.world.segments.push({
        id: "bat_descending_steep_line", kind: "blockable", x1: 680, y1: 280, x2: 720, y2: 360
    });
    const descendingBlockedBat = descendingFlightState.enemies.find((enemy) => enemy.id === "descending_blocked_bat");
    let maximumDescendingBatY = descendingBlockedBat.currentTransform.y;
    for (let step = 0; step < 30; step += 1) {
        stepSimulation(descendingFlightState, createInputFrame(), FIXED_DT);
        maximumDescendingBatY = Math.max(maximumDescendingBatY, descendingBlockedBat.currentTransform.y);
    }
    assert.ok(maximumDescendingBatY <= 322,
        `a descending flyer should be stopped by a steep blockable line; max y=${maximumDescendingBatY}`);
    assert.ok(descendingBlockedBat.health > 0 && descendingBlockedBat.combatState !== "dead",
        "steep-line vertical obstruction should preserve the flying enemy rather than letting it pass or killing it");
    assert.equal(descendingBlockedBat.supportId, null, "vertical flyer obstruction must not create grounded support");

    const stackedVerticalFlightState = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(stackedVerticalFlightState, {
        levelId: "bat_walkable_before_blocker_flight_test",
        testPlayerStart: { x: 100, y: 700 },
        world: { bounds: { x: 0, y: 0, w: 1400, h: 1000 } },
        entities: [{
            id: "stacked_vertical_bat", type: "characterEnemy", characterId: "ct_char_enemy_020",
            x: 700, y: 280, w: 84, h: 66, facing: 1, strategy: "simple_patrol", locomotion: "flying",
            patrolDistance: 0, walkSpeed: 0, flightAmplitude: 100, flightCyclesPerSecond: 1, flightPhaseOffset: 0.25,
            health: 1, animationSlot: "fly"
        }]
    }), true, "stacked one-way/blocker flying regression level should apply");
    stackedVerticalFlightState.story.portalIntro = null;
    stackedVerticalFlightState.story.portalExit = null;
    stackedVerticalFlightState.world.segments.push(
        { id: "stacked_flight_one_way", kind: "walkable", x1: 600, y1: 300, x2: 800, y2: 300 },
        { id: "stacked_flight_blocker", kind: "blockable", x1: 600, y1: 320, x2: 800, y2: 320 }
    );
    const stackedVerticalBat = stackedVerticalFlightState.enemies.find((enemy) => enemy.id === "stacked_vertical_bat");
    stepSimulation(stackedVerticalFlightState, createInputFrame(), FIXED_DT);
    assert.ok(Math.abs(stackedVerticalBat.currentTransform.y - 320) < 0.000001,
        `a flyer should ignore a nearer one-way line before nearest-hit selection and stop on the blocker behind it; y=${stackedVerticalBat.currentTransform.y}`);
    assert.equal(stackedVerticalBat.supportId, null,
        "a blocker behind an ignored one-way line must not ground flying locomotion");
    assert.ok(stackedVerticalBat.health > 0 && stackedVerticalBat.combatState !== "dead",
        "stacked one-way/blocker flight collision should preserve the flying enemy");

    bat.health = 0;
    bat.combatState = "dead";
    const deathStartX = bat.currentTransform.x;
    const fadeStartElapsed = bat.deathFlyOffDistance / bat.deathFlightSpeed;
    while (bat.deathElapsed < fadeStartElapsed + bat.corpseFadeDuration * 0.5) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    assert.ok(bat.currentTransform.x > deathStartX + 720, "defeated bat should complete its original fly-off distance before the fade is well underway");
    assert.ok(bat.currentTransform.alpha > 0 && bat.currentTransform.alpha < 1, "defeated bat should fade gradually during its extended fly-off");
    const fadingX = bat.currentTransform.x;
    const fadingAlpha = bat.currentTransform.alpha;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    assert.ok(bat.currentTransform.x > fadingX, "defeated bat should keep flying horizontally while it fades");
    assert.ok(bat.currentTransform.alpha < fadingAlpha, "defeated bat opacity should continue decreasing while it flies");
    for (let step = 0; step < 180 && bat.currentTransform.alpha > 0; step += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    assert.ok(bat.currentTransform.x > deathStartX + 1100, "defeated bat should travel substantially farther than the former fly-off distance before disappearing");
    assert.equal(bat.currentTransform.alpha, 0, "defeated bat should disappear only after completing its moving fade-out");
    assert.equal(bat.movementPhase, "death_fly_off", "defeated bat should expose its dedicated fly-off state");
    assert.equal(bat.animationSlot, "fly", "death fly-off should keep flapping rather than requiring a fabricated corpse clip");
    assert.equal(bat.simulationDormant, true, "SDL parity: a completed flying death should become simulation-dormant");
    const dormantX = bat.currentTransform.x;
    const dormantY = bat.currentTransform.y;
    const dormantElapsed = bat.deathElapsed;
    stepMany(state, 60);
    approx(bat.currentTransform.x, dormantX, 0.000001, "a dormant flying corpse should stop updating x");
    approx(bat.currentTransform.y, dormantY, 0.000001, "a dormant flying corpse should stop updating y");
    approx(bat.deathElapsed, dormantElapsed, 0.000001, "a dormant flying corpse should stop consuming simulation time");
}


function testFlyingBomberDropsProjectile() {
    const state = createInitialGameState();
    applyEditorLevelToWorld(state, {
        levelId: "bomber_test",
        testPlayerStart: { x: 500, y: 620 },
        bounds: { x: 0, y: 0, w: 1200, h: 800 },
        entities: [{
            id: "bomber",
            type: "characterEnemy",
            characterId: "ct_char_enemy_020",
            x: 220,
            y: 300,
            w: 84,
            h: 66,
            locomotion: "flying",
            strategy: "bomber",
            bomberHorizontalSpeed: 240,
            bomberHoverHeight: 180,
            bomberDropTolerance: 24,
            bomberInitialDelay: 0,
            awarenessRange: 0,
            awarenessViewHalfAngle: 180,
            projectileLaunchType: "drop",
            projectileKind: "rock",
            projectileRendererKind: "enemyRock",
            projectileVisualScale: 1,
            projectileRotationSpeedDegrees: 286.4788975654116,
            projectileTrailEffect: "none",
            projectileImpactEffect: "sparks",
            projectileExplosionEffect: "impact",
            projectileSpeed: 20,
            projectileGravity: 900,
            attackCooldown: 1.5,
            damage: 12,
            projectileRadius: 10,
            health: 1,
            animationSlot: "fly"
        }]
    });
    const bomber = state.enemies.find((enemy) => enemy.id === "bomber");
    state.world.solids.push({ id: "bomber_test_floor", kind: "floor", x: 0, y: 620, w: 1200, h: 180 });
    state.player.onGround = true;
    state.player.wasOnGround = true;
    assert.equal(bomber.strategy, "bomber", "portable enemy state should preserve bomber strategy");
    const perchX = bomber.currentTransform.x;
    const perchY = bomber.currentTransform.y;
    state.player.visible = false;
    for (let step = 0; step < 60; step += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    assert.equal(bomber.aiState, "perched", "bomber should wait at its authored perch while Ignatius is outside awareness");
    assert.ok(Math.abs(bomber.currentTransform.x - perchX) < 0.01 && Math.abs(bomber.currentTransform.y - perchY) < 0.01, "perched bomber should remain at its authored position");
    state.player.visible = true;
    bomber.awarenessRange = 800;
    state.player.currentTransform.x = 500;
    for (let step = 0; step < 240 && state.projectiles.length === 0; step += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
    }
    assert.ok(Math.abs(bomber.currentTransform.x - state.player.currentTransform.x) <= 12, "bomber should cross directly over Ignatius before releasing");
    assert.ok(state.projectiles.length > 0, "bomber should drop a projectile when horizontally aligned");
    const releaseHeight = state.player.currentTransform.y - bomber.currentTransform.y;
    assert.ok(
        Math.abs(releaseHeight - bomber.bomberHoverHeight) <= bomber.bomberDropHeightTolerance + 8,
        `bomber should reach its authored bombing altitude before releasing, got ${releaseHeight.toFixed(1)} for target ${bomber.bomberHoverHeight}`
    );
    const bomb = state.projectiles[0];
    assert.equal(bomb.launchType, "drop", "bomber projectile should use the drop launch type");
    assert.equal(bomb.kind, "enemyRock", "bomber should drop a dedicated rock projectile");
    assert.ok(bomb.gravity > 0, "dropped projectile should accelerate downward");
    assert.ok(bomb.vy >= 0, "dropped projectile should begin moving downward");

    // Awareness ownership regression: once sight is lost, the flying bomber itself
    // owns the hold timer. It must consume one fixed-step quantum per fixed step,
    // not also pass through the generic non-hunter awareness prepass.
    state.player.visible = false;
    bomber.awarenessTimer = 1.2;
    bomber.awarenessHoldDuration = 1.2;
    let holdTicks = 0;
    while (bomber.awarenessTimer > 0.000001 && holdTicks < 400) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        holdTicks += 1;
    }
    approx(holdTicks * FIXED_DT, 1.2, FIXED_DT + 0.000001, "flying bomber should retain its authored 1.2-second awareness hold after losing sight");
}

