function testEngagedHunterImmediatelyLeavesPillarForLastSeenPlayer() {
    const level = JSON.parse(readFileSync("./resources/levels/level_t01.json", "utf8"));
    level.entities = level.entities.filter((entity) => entity.type !== "characterEnemy" || entity.id === "enemy_010_001");
    const rememberedFloorSupportId = bakedNavigationSupportIdAt(level, 70, 105, "floor_cold_platform_001_blockable_2", 1700);
    assert.ok(rememberedFloorSupportId, "level_t01 goblin graph should retain the remembered broad-floor position");

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "level_t01 should apply for the ledge-exit awareness regression test");
    const manifests = new Map();
    for (const ref of level.atlasRefs || []) {
        const path = resourceFileUrl(ref.manifest);
        manifests.set(ref.atlasId, { manifest: JSON.parse(readFileSync(path, "utf8")) });
    }
    assert.equal(applyAtlasManifestsToWorld(state, manifests), true, "level collision should apply for the ledge-exit awareness regression test");
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 1700;
    state.player.currentTransform.y = 844.35;
    state.player.onGround = true;
    state.player.wasOnGround = true;
    state.player.visible = true;

    const enemy = state.enemies.find((item) => item.id === "enemy_010_001");
    assert.ok(enemy, "level_t01 should instantiate the fireball goblin used by the ledge-exit regression test");
    enemy.currentTransform.x = 1550;
    enemy.currentTransform.y = 658.5;
    enemy.homeX = 1550;
    enemy.homeY = 658.5;
    enemy.currentSupportId = "object_036_001_blockable_1";
    enemy.supportId = "object_036_001_blockable_1";
    enemy.homeSupportId = "object_036_001_blockable_1";
    enemy.facing = 1;
    enemy.awarenessRange = 2000;
    enemy.awarenessViewHalfAngle = 45;
    enemy.awarenessTimer = 1.5;
    enemy.lastSeenPlayerX = state.player.currentTransform.x;
    enemy.lastSeenPlayerY = state.player.currentTransform.y;
    enemy.lastSeenSupportId = rememberedFloorSupportId;
    enemy.engaged = true;
    enemy.alerted = true;
    enemy.aiState = "pursue";
    enemy.routeRepathTimer = 0;

    const startX = enemy.currentTransform.x;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    const firstEdge = enemy.route?.[enemy.routeIndex];
    assert.equal(enemy.aiState, "investigate_last_seen", "losing the narrow facing cone should begin last-seen pursuit immediately instead of idling through the awareness hold");
    assert.equal(enemy.routePurpose, "last_seen", "the immediate pursuit should use the genuinely remembered player position");
    assert.equal(firstEdge?.to, rememberedFloorSupportId, "the remembered lower-floor position should produce an exit route from the pillar");
    assert.ok(enemy.currentTransform.x > startX, "the short downward-jump run-up should move toward the nearby right edge instead of backing across the whole ledge");

    let launchFrame = null;
    for (let frame = 1; frame < 90; frame += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        if (enemy.airborne) {
            launchFrame = frame;
            break;
        }
    }
    assert.ok(launchFrame !== null, "the hunter should commit to leaving the ledge");
    assert.ok(launchFrame < 60, `the ledge exit should launch promptly rather than looking stuck, launched on frame ${launchFrame}`);
}

function testHunterWalksOffLevelOneLeftLedge() {
    const level = JSON.parse(readFileSync("./resources/levels/level_t01.json", "utf8"));
    level.entities = level.entities.filter((entity) => entity.type !== "characterEnemy" || entity.id === "enemy_010_001");
    const lowerFloorSupportId = bakedNavigationSupportIdAt(level, 70, 105, "floor_cold_platform_001_blockable_2", 1000);
    assert.ok(lowerFloorSupportId, "level_t01 goblin graph should retain the lower landing floor below the left ledge");

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "level_t01 should apply for the long ledge walk-off regression test");
    const manifests = new Map();
    for (const ref of level.atlasRefs || []) {
        const path = resourceFileUrl(ref.manifest);
        manifests.set(ref.atlasId, { manifest: JSON.parse(readFileSync(path, "utf8")) });
    }
    assert.equal(applyAtlasManifestsToWorld(state, manifests), true, "level collision should apply for the long ledge walk-off regression test");
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 1700;
    state.player.currentTransform.y = 844.33;
    state.player.onGround = true;
    state.player.wasOnGround = true;
    state.player.visible = true;

    const enemy = state.enemies.find((item) => item.id === "enemy_010_001");
    assert.ok(enemy, "level_t01 should instantiate the fireball goblin used by the long ledge regression test");
    enemy.currentTransform.x = 970;
    enemy.currentTransform.y = 289.33;
    enemy.spawnX = 970;
    enemy.spawnY = 289.33;
    enemy.homeSupportId = "left_step_blockable_1";
    enemy.currentSupportId = "left_step_blockable_1";
    enemy.supportId = "left_step_blockable_1";
    enemy.facing = 1;
    enemy.awarenessRange = 2000;
    enemy.engaged = true;
    enemy.alerted = true;
    enemy.aiState = "pursue";
    enemy.routeRepathTimer = 0;

    stepSimulation(state, createInputFrame(), FIXED_DT);
    const firstEdge = enemy.route?.[enemy.routeIndex];
    assert.notEqual(enemy.aiState, "unreachable_glare", "the visible lower target should not be classified as unreachable from the ledge");
    assert.equal(firstEdge?.type, "drop", "the hunter should choose a gravity-only drop instead of jumping from the ledge");
    assert.equal(firstEdge?.walkOff, true, "the descent should be marked as a controlled walk-off");
    assert.equal(firstEdge?.direction, "right", "the hunter should leave from the edge facing the wizard");
    assert.equal(firstEdge?.to, lowerFloorSupportId, "the walk-off should land on the verified floor below");
    assert.equal(firstEdge?.vy, 0, "walking off should not add an upward jump impulse");

    let sawDrop = false;
    let landed = false;
    for (let frame = 1; frame < 120; frame += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        sawDrop ||= enemy.airborne && enemy.aiState === "drop";
        landed ||= sawDrop && !enemy.airborne && enemy.currentSupportId === lowerFloorSupportId;
        if (landed) break;
    }
    if (sawDrop) {
        assert.equal(landed, true, "a committed walk-off should land on the lower floor and continue pursuit");
        assert.equal(enemy.navigationFailureCount, 0, "a successful controlled walk-off should not count as a navigation failure");
    } else {
        // A heuristic ballistic proposal is allowed to lose its physical vote.
        // It is acceptable for an occasional ledge to become unreachable; the
        // important runtime contract is to reject it promptly rather than stall,
        // teleport, or wait for the hunter watchdog to recover the mistake.
        assert.equal(landed, false, "a rejected walk-off must not report a phantom landing");
        assert.equal(enemy.aiState, "unreachable_glare", "a physically rejected ledge exit should degrade to the ordinary unreachable state");
        assert.ok(Object.values(enemy.navigationTransitionFailures || {}).some((failure) =>
            String(failure?.reason || "").includes("run_up")),
        "a rejected ledge exit should record the physical run-up failure");
        assert.equal(Number(enemy.hunterWatchdogTimeoutCount) || 0, 0, "the ledge rejection should not need watchdog recovery");
    }
}


