function testSkeletonCasterPursuesOntoLevelOneRuin() {
    const level = JSON.parse(readFileSync("./resources/levels/level_t01.json", "utf8"));
    const catalog = JSON.parse(readFileSync("./resources/characters/ct_enemies_001.json", "utf8"));
    level.autoSpawnEnemies = { enabled: false, probabilityPercent: 0, enemyPool: "1-999" };
    level.entities = level.entities.filter((entity) => entity.type !== "characterEnemy");
    level.entities.push(enemyEntityFromDefinition(catalog, "enemy_002", {
        id: "skeleton_caster_ruin_test",
        x: 2860,
        y: 844.55,
        homeX: 2860,
        homeY: 844.55,
        facing: 1
    }));

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "level_t01 should apply for the Skeleton Caster ruin-pursuit regression test");
    const manifests = new Map();
    for (const ref of level.atlasRefs || []) {
        const path = resourceFileUrl(ref.manifest);
        manifests.set(ref.atlasId, { manifest: JSON.parse(readFileSync(path, "utf8")) });
    }
    assert.equal(applyAtlasManifestsToWorld(state, manifests), true, "level collision should apply for the Skeleton Caster ruin-pursuit regression test");
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    state.player.currentTransform.x = 3310;
    state.player.currentTransform.y = 683;
    state.player.onGround = true;
    state.player.wasOnGround = true;
    state.player.visible = true;

    const enemy = state.enemies.find((item) => item.id === "skeleton_caster_ruin_test");
    assert.ok(enemy, "the regression should instantiate the Skeleton Caster");
    enemy.awarenessRange = 2000;
    enemy.facing = 1;

    let plannedPlayerSupport = false;
    let launchedTowardRuin = false;
    let landedOnRuin = false;
    for (let frame = 0; frame < 260; frame += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        plannedPlayerSupport ||= enemy.routePurpose === "pursue" && enemy.routeTargetSupportId === "arch_ruin_001_blockable_4";
        launchedTowardRuin ||= enemy.airborne && enemy.route?.[enemy.routeIndex]?.to === "arch_ruin_001_blockable_1";
        landedOnRuin ||= launchedTowardRuin && !enemy.airborne && String(enemy.currentSupportId || "").startsWith("arch_ruin_001_blockable_");
        if (landedOnRuin) break;
    }

    if (plannedPlayerSupport || launchedTowardRuin || landedOnRuin) {
        assert.equal(plannedPlayerSupport, true, "a caster choosing the ruin route should target Ignatius's actual ruin support");
        assert.equal(launchedTowardRuin, true, "a caster choosing the ruin route should commit to the jump");
        assert.equal(landedOnRuin, true, "a committed ruin jump should land on the ruin and continue the hunt");
        assert.equal(enemy.navigationFailureCount, 0, "a successful ruin approach should not register navigation failures");
    } else {
        // Sparse heuristic graphs are allowed to omit an occasional optional
        // platform. The caster must remain in a normal tactical/fallback state
        // rather than depending on watchdog recovery or teleporting there.
        assert.ok(["pursue", "investigate_last_seen", "unreachable_glare", "return_home", "patrol"].includes(enemy.aiState),
            `an omitted ruin route should leave the caster in an ordinary AI state, got ${enemy.aiState}`);
        assert.equal(Number(enemy.hunterWatchdogTimeoutCount) || 0, 0, "an omitted optional ruin route should not require watchdog recovery");
        assert.equal(enemy.airborne, false, "the caster must not report a phantom ruin jump when no ruin route was chosen");
    }
}

