function testGroundEnemyCannotDropThroughOneWayPlatform() {
    const world = {
        segments: [
            { id: "upper_one_way", kind: "walkable", x1: 0, y1: 400, x2: 300, y2: 400 },
            { id: "lower_floor", kind: "walkable", x1: -220, y1: 600, x2: 520, y2: 600 }
        ],
        solids: [],
        collisionPolygons: []
    };
    const profile = {
        bodyWidth: 72,
        bodyHeight: 150,
        runSpeed: 180,
        jumpHeight: 180,
        gravity: 1200,
        maxFallDistance: 300,
        maxStepHeight: 26,
        maxStepGap: 18,
        edgeInset: 12
    };
    const graph = bakeEnemyNavigationGraph(world, profile, { id: "one_way_drop_guard" });
    const descents = graph.edges.filter((edge) => edge.from === "upper_one_way" && edge.to === "lower_floor" && edge.type === "drop");
    assert.ok(descents.length > 0, "a monster should still be able to leave a one-way platform by walking off an exposed edge");
    assert.equal(descents.every((edge) => edge.walkOff === true), true, "every descent from a green one-way support must be an edge walk-off");
    assert.equal(descents.every((edge) => Math.abs(edge.vx) > 0.001 && edge.direction !== "down"), true, "one-way navigation must never encode a straight drop through the support line");
    assert.equal(descents.every((edge) => edge.launchX <= 2.6 || edge.launchX >= 297.4), true, "one-way walk-offs should launch only at an authored platform end");

    const narrowGapWorld = {
        segments: [
            { id: "narrow_gap_left", kind: "walkable", x1: 0, y1: 400, x2: 100, y2: 400 },
            { id: "narrow_gap_right", kind: "walkable", x1: 106.66, y1: 400, x2: 300, y2: 400 },
            { id: "narrow_gap_lower", kind: "walkable", x1: -300, y1: 650, x2: 600, y2: 650 }
        ],
        solids: [],
        collisionPolygons: []
    };
    const narrowGapSupports = buildEnemyNavigationSupports(narrowGapWorld, profile);
    const narrowGapEdges = buildEnemyNavigationEdges(narrowGapSupports, { ...profile, world: narrowGapWorld });
    const leftGapDrops = narrowGapEdges.get("narrow_gap_left")?.filter((edge) => edge.type === "drop" && edge.to === "narrow_gap_lower") || [];
    const rightGapDrops = narrowGapEdges.get("narrow_gap_right")?.filter((edge) => edge.type === "drop" && edge.to === "narrow_gap_lower") || [];
    assert.equal(leftGapDrops.some((edge) => edge.direction === "right"), false, "a 72 px actor must not treat a 6.66 px same-height gap as an exposed right-hand drop");
    assert.equal(rightGapDrops.some((edge) => edge.direction === "left"), false, "a 72 px actor must not treat a 6.66 px same-height gap as an exposed left-hand drop");
    assert.equal(leftGapDrops.some((edge) => edge.direction === "left"), true, "the true outer left endpoint should remain a valid walk-off");
    assert.equal(rightGapDrops.some((edge) => edge.direction === "right"), true, "the true outer right endpoint should remain a valid walk-off");

    const verticallyOffsetGapWorld = {
        segments: [
            { id: "offset_gap_left", kind: "walkable", x1: 0, y1: 400, x2: 100, y2: 400 },
            { id: "offset_gap_right", kind: "walkable", x1: 106.66, y1: 402, x2: 300, y2: 402 },
            { id: "offset_gap_lower", kind: "walkable", x1: -300, y1: 650, x2: 600, y2: 650 }
        ],
        solids: [],
        collisionPolygons: []
    };
    const verticallyOffsetSupports = buildEnemyNavigationSupports(verticallyOffsetGapWorld, profile);
    const verticallyOffsetEdges = buildEnemyNavigationEdges(verticallyOffsetSupports, { ...profile, world: verticallyOffsetGapWorld });
    const offsetLeftDrops = verticallyOffsetEdges.get("offset_gap_left")?.filter((edge) => edge.type === "drop" && edge.to === "offset_gap_lower") || [];
    assert.equal(offsetLeftDrops.some((edge) => edge.direction === "right"), false, "a neighbouring one-way line 2 px lower must still block a walk-off that runtime feet immediately catch");

    const staleNarrowGapEdge = {
        type: "drop",
        direction: "right",
        from: "narrow_gap_left",
        to: "narrow_gap_lower",
        launchX: 98.1,
        launchY: 400,
        landingX: 160,
        landingY: 650,
        vx: 75,
        vy: 0,
        flightTime: 0.6,
        walkOff: true,
        cost: 1,
        blockerIds: []
    };
    const narrowGapLeftSupport = narrowGapSupports.find((support) => support.id === "narrow_gap_left");
    assert.equal(
        enemyNavigationTraversalAllowedFromSupport(staleNarrowGapEdge, narrowGapLeftSupport, narrowGapSupports, profile),
        false,
        "runtime traversal policy should reject an already-baked narrow-gap walk-off edge"
    );
    const offsetGapLeftSupport = verticallyOffsetSupports.find((support) => support.id === "offset_gap_left");
    const staleOffsetGapEdge = { ...staleNarrowGapEdge, from: "offset_gap_left", to: "offset_gap_lower" };
    assert.equal(
        enemyNavigationTraversalAllowedFromSupport(staleOffsetGapEdge, offsetGapLeftSupport, verticallyOffsetSupports, profile),
        false,
        "runtime traversal policy should reject a stale walk-off when a neighbouring one-way line 2 px lower catches the first descent tick"
    );

    // Regression geometry distilled from the angled rope-ladder cluster that
    // exposed the sloped-neighbour early-exit bug. The neighbouring green line
    // descends into the actor's departure path even though its near endpoint is
    // already below the source. It must block a drop to some other destination,
    // while remaining legal when that sloped line is itself the intended target.
    const slopedSource = {
        id: "sloped_source", kind: "walkable",
        x1: 18013, y1: 1830, x2: 17916, y2: 1559, xMin: 17916, xMax: 18013
    };
    const slopedNeighbour = {
        id: "sloped_neighbour", kind: "walkable",
        x1: 18045, y1: 1926, x2: 17948, y2: 1655, xMin: 17948, xMax: 18045
    };
    const slopedTarget = {
        id: "sloped_target", kind: "blockable",
        x1: 17944.3058, y1: 1919.2, x2: 19313.6942, y2: 1919.2,
        xMin: 17944.3058, xMax: 19313.6942
    };
    const slopedProfile = {
        bodyWidth: 34, bodyHeight: 104, runSpeed: 360, groundAcceleration: 950,
        jumpHeight: 200, gravity: 1490, maxFallDistance: 696.806,
        maxStepHeight: 20.8, maxStepGap: 10.88, edgeInset: 7.48, bodyClearance: 11.56
    };
    const staleSlopedDrop = {
        type: "drop", direction: "right", from: "sloped_source", to: "sloped_target",
        launchX: 18012.102, launchY: 1827.492, landingX: 18138.409, landingY: 1919.2,
        vx: 360, vy: 0, walkOff: true, cost: 1, blockerIds: []
    };
    assert.equal(
        enemyNavigationTraversalAllowedFromSupport(
            staleSlopedDrop, slopedSource, [slopedSource, slopedNeighbour, slopedTarget], slopedProfile
        ),
        false,
        "runtime traversal policy should reject a walk-off intercepted a few ticks later by a descending neighbouring one-way line"
    );
    assert.equal(
        enemyNavigationTraversalAllowedFromSupport(
            { ...staleSlopedDrop, to: "sloped_neighbour", landingX: 18040, landingY: 1912 },
            slopedSource, [slopedSource, slopedNeighbour, slopedTarget], slopedProfile
        ),
        true,
        "walk-off validation should allow an early one-way catch when that sloped support is the intended destination"
    );

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "enemy_one_way_drop_guard_test",
        testPlayerStart: { x: 150, y: 600 },
        entities: [{
            id: "drop_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 150,
            y: 400,
            w: 72,
            h: 150,
            facing: 1,
            strategy: "hunter",
            patrolDistance: 80,
            walkSpeed: 40,
            runSpeed: 180,
            jumpHeight: 180,
            jumpGravity: 1200,
            maxFallDistance: 300,
            maxStepHeight: 26,
            awarenessRange: 800,
            attackType: "melee",
            damage: 0
        }]
    }), true, "one-way drop-guard fixture should apply");
    state.world.segments = world.segments.map((segment) => ({ ...segment }));
    state.world.solids = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;

    const enemy = state.enemies.find((item) => item.id === "drop_guard");
    // Simulate a stale pre-fix graph that asks for a zero-horizontal drop. The
    // runtime collision guard must reject it even if such an edge reaches play.
    enemy.airborne = true;
    enemy.airTimer = 0;
    enemy.airTraversalType = "drop";
    enemy.airSourceSupportId = "upper_one_way";
    enemy.airSourceObstacleId = null;
    enemy.airTargetSupportId = "lower_floor";
    enemy.currentSupportId = "upper_one_way";
    enemy.supportId = null;
    enemy.velocityX = 0;
    enemy.velocityY = 0;
    enemy.aiState = "drop";
    enemy.movementPhase = "drop";

    stepSimulation(state, createInputFrame(), FIXED_DT);
    assert.equal(enemy.airborne, false, "a malformed direct-drop request should land back on the green support instead of passing through it");
    assert.equal(enemy.currentTransform.y, 400, "the one-way support should remain authoritative under the monster's feet");
}

function testHunterDoesNotJumpLoopOnOneWayPlatform() {
    const world = {
        segments: [
            { id: "upper_green", kind: "walkable", x1: 0, y1: 400, x2: 600, y2: 400 },
            { id: "lower_yellow", kind: "blockable", x1: -100, y1: 650, x2: 900, y2: 650 }
        ],
        solids: [],
        collisionPolygons: []
    };
    const profile = {
        bodyWidth: 72,
        bodyHeight: 150,
        runSpeed: 180,
        groundAcceleration: 950,
        jumpHeight: 180,
        gravity: 1200,
        maxFallDistance: 400,
        maxStepHeight: 26,
        maxStepGap: 23.04,
        edgeInset: 15.84,
        bodyClearance: 24.48
    };
    const baked = bakeEnemyNavigationGraph(world, profile, { id: "one_way_jump_loop_guard" });
    const descents = baked.edges.filter((edge) => edge.from === "upper_green" && edge.to === "lower_yellow");
    assert.ok(descents.length > 0, "the hunter should retain a route from the upper one-way platform to the lower floor");
    assert.equal(descents.some((edge) => edge.type === "step"), false, "one-way descent planning must not create an ordinary ground step through the platform");
    assert.equal(descents.every((edge) => edge.type === "jump" || (edge.type === "drop" && edge.walkOff === true)), true,
        "one-way descents should be deliberate jumps or exposed-endpoint walk-off drops");

    // Add a deliberately cheap downward jump-through edge. WIP16 accepted
    // this policy for green one-way supports, so route planning and execution
    // must agree: the committed jump may pass back through only its source line
    // and must complete on the lower support without entering a retry loop.
    baked.edges.unshift({
        id: "legacy_vertical_jump_through_green",
        type: "jump",
        direction: "up",
        from: "upper_green",
        to: "lower_yellow",
        launchX: 300,
        launchY: 400,
        landingX: 300,
        landingY: 650,
        vx: 0,
        vy: -Math.sqrt(2 * profile.gravity * profile.jumpHeight),
        flightTime: 1.4,
        cost: 1,
        blockerIds: []
    });

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "hunter_one_way_jump_loop_test",
        testPlayerStart: { x: 300, y: 650 },
        entities: [{
            id: "loop_guard",
            type: "characterEnemy",
            characterId: "ct_char_enemy_001",
            x: 300,
            y: 400,
            w: 72,
            h: 150,
            facing: 1,
            strategy: "hunter",
            patrolDistance: 80,
            walkSpeed: 40,
            runSpeed: 180,
            runAcceleration: 950,
            jumpHeight: 180,
            jumpGravity: 1200,
            maxFallDistance: 400,
            maxStepHeight: 26,
            awarenessRange: 1200,
            awarenessHalfAngle: 180,
            attackType: "melee",
            attackRange: 60,
            attackVerticalRange: 110,
            damage: 0
        }],
        navigationGraphs: { version: 2, profiles: [baked] }
    }), true, "one-way jump-loop fixture should apply");
    state.world.segments = world.segments.map((segment) => ({ ...segment }));
    state.world.solids = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    Object.assign(state.player, { x: 300, y: 650, onGround: true, wasOnGround: true });

    const enemy = state.enemies.find((item) => item.id === "loop_guard");
    Object.assign(enemy, {
        alerted: true,
        engaged: true,
        aiState: "pursue",
        awarenessTimer: 10,
        lastSeenPlayerX: 300,
        lastSeenPlayerY: 650,
        lastSeenSupportId: "lower_yellow",
        routeRepathTimer: 0
    });

    const launches = [];
    let wasAirborne = false;
    for (let tick = 0; tick < 600; tick += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        if (enemy.airborne && !wasAirborne) {
            launches.push(enemy.airTraversalType);
        }
        wasAirborne = enemy.airborne;
    }
    assert.equal(enemy.navigationGraphSource, "baked", "the one-way jump-through regression should exercise baked-graph planning");
    assert.equal(launches.filter((type) => type === "jump").length, 1, "the accepted downward jump-through should execute exactly once instead of retry-looping on its source green line");
    assert.equal(enemy.currentSupportId, "lower_yellow", "the committed downward jump-through should complete on the lower support");
    assert.equal(enemy.currentTransform.y, 650, "the committed downward jump-through should land on the lower support");
}

function testHunterDoesNotWalkOffInternalSegmentSeam() {
    const world = {
        segments: [
            { id: "upper_a", kind: "walkable", x1: 0, y1: 400, x2: 100, y2: 410 },
            { id: "upper_b", kind: "walkable", x1: 100, y1: 410, x2: 200, y2: 420 },
            { id: "lower", kind: "blockable", x1: -220, y1: 650, x2: 420, y2: 650 }
        ],
        solids: [],
        collisionPolygons: []
    };
    const profile = {
        bodyWidth: 70,
        bodyHeight: 105,
        runSpeed: 250,
        groundAcceleration: 950,
        jumpHeight: 250,
        gravity: 1250,
        maxFallDistance: 600,
        maxStepHeight: 26,
        maxStepGap: 22.4,
        edgeInset: 15.4,
        bodyClearance: 23.8
    };
    const baked = bakeEnemyNavigationGraph(world, profile, { id: "segmented_one_way_drop_guard" });
    assert.equal(
        baked.edges.some((edge) => edge.type === "drop" && (
            (edge.from === "upper_b" && edge.direction === "left" && edge.launchX < 104) ||
            (edge.from === "upper_a" && edge.direction === "right" && edge.launchX > 96)
        )),
        false,
        "the baker should not advertise internal walkable seams as exposed drop ledges"
    );
    assert.ok(
        baked.edges.some((edge) => edge.type === "drop" && (
            (edge.from === "upper_a" && edge.direction === "left") ||
            (edge.from === "upper_b" && edge.direction === "right")
        )),
        "the baker should retain genuinely exposed outer-edge drops"
    );

    const state = createCatalogBackedGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "hunter_segmented_one_way_drop_test",
        testPlayerStart: { x: -100, y: 650 },
        entities: [{
            id: "seam_hunter",
            type: "characterEnemy",
            characterId: "ct_char_enemy_012",
            x: 150,
            y: 415,
            w: 70,
            h: 105,
            facing: -1,
            strategy: "hunter",
            patrolDistance: 80,
            walkSpeed: 54,
            runSpeed: 250,
            runAcceleration: 950,
            jumpHeight: 250,
            jumpGravity: 1250,
            maxFallDistance: 600,
            maxStepHeight: 26,
            awarenessRange: 1400,
            awarenessHalfAngle: 180,
            attackType: "melee",
            attackRange: 50,
            attackVerticalRange: 110,
            damage: 0
        }],
        navigationGraphs: { version: 2, profiles: [baked] }
    }), true, "segmented one-way drop fixture should apply");
    state.world.segments = world.segments.map((segment) => ({ ...segment }));
    state.world.solids = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;
    Object.assign(state.player, { x: -100, y: 650, onGround: true, wasOnGround: true, supportId: "lower" });

    const enemy = state.enemies.find((item) => item.id === "seam_hunter");
    Object.assign(enemy, {
        alerted: true,
        engaged: true,
        aiState: "pursue",
        awarenessTimer: 10,
        lastSeenPlayerX: -100,
        lastSeenPlayerY: 650,
        lastSeenSupportId: "lower",
        routeRepathTimer: 0,
        currentSupportId: "upper_b",
        supportId: "upper_b"
    });

    const launches = [];
    let wasAirborne = false;
    for (let tick = 0; tick < 600; tick += 1) {
        stepSimulation(state, createInputFrame(), FIXED_DT);
        if (enemy.airborne && !wasAirborne) {
            launches.push({
                type: enemy.airTraversalType,
                source: enemy.airSourceSupportId,
                x: enemy.currentTransform.x,
                vx: enemy.velocityX
            });
        }
        wasAirborne = enemy.airborne;
        if (enemy.currentSupportId === "lower" && !enemy.airborne) {
            break;
        }
    }
    assert.equal(enemy.navigationGraphSource, "baked", "segmented seam regression should exercise the baked graph");
    assert.equal(
        launches.some((launch) => launch.source === "upper_b" && launch.vx < 0 && launch.x < 104),
        false,
        "the internal seam between contiguous walkable segments must not be treated as an exposed left ledge"
    );
    assert.equal(
        launches.some((launch) => launch.source === "upper_a" && launch.vx > 0 && launch.x > 96),
        false,
        "the same internal seam must not be treated as an exposed right ledge from the neighbouring segment"
    );
    assert.ok(
        launches.some((launch) => launch.type === "drop" && (
            (launch.source === "upper_a" && launch.vx < 0) ||
            (launch.source === "upper_b" && launch.vx > 0)
        )),
        "the hunter should use a genuinely exposed outer ledge instead of the internal seam"
    );
    assert.equal(enemy.currentSupportId, "lower", "the hunter should complete the real drop instead of bouncing between top segments");
}

function testPlayerCanDropThroughOneWayPlatforms() {
    const state = createCatalogBackedGameState();
    state.world.segments = [
        { id: "upper_green", kind: "walkable", x1: -240, y1: 400, x2: 240, y2: 400 },
        { id: "lower_yellow", kind: "blockable", x1: -240, y1: 600, x2: 240, y2: 600 }
    ];
    state.world.solids = [];
    state.world.collisionPolygons = [];
    state.story.portalIntro = null;
    state.story.portalExit = null;
    state.story.mailboxEvent = null;

    const rocketState = createInitialGameState();
    rocketState.world.segments = structuredClone(state.world.segments);
    rocketState.world.solids = [];
    rocketState.world.collisionPolygons = [];
    rocketState.story.portalIntro = null;
    rocketState.story.portalExit = null;
    rocketState.story.mailboxEvent = null;
    Object.assign(rocketState.player.currentTransform, { x: 0, y: 400 });
    Object.assign(rocketState.player.previousTransform, rocketState.player.currentTransform);
    Object.assign(rocketState.player.shownTransform, rocketState.player.currentTransform);
    Object.assign(rocketState.player, {
        vx: 0,
        vy: 0,
        onGround: true,
        wasOnGround: true,
        supportId: "upper_green",
        dropThroughTimer: 0,
        ordinaryJumpActive: false,
        airBoostArmed: false
    });
    stepSimulation(rocketState, createInputFrame(), FIXED_DT);
    assert.equal(rocketState.player.airBoostArmed, true, "standing on support should arm the first airborne rocket kick");
    stepSimulation(rocketState, createInputFrame({ dropPressed: true, dropHeld: true }), FIXED_DT);
    assert.equal(rocketState.player.onGround, false, "Down should release the grounded wizard through the green line");
    assert.equal(rocketState.player.airBoostArmed, true, "dropping through a green line should preserve the grounded rocket kick");
    stepSimulation(rocketState, createInputFrame({ jumpPressed: true, jumpHeld: true }), FIXED_DT);
    assert.equal(rocketState.equipment.rocket.attachedBoosting, true, "the first Up press after drop-through should start the rocket immediately");

    Object.assign(state.player, {
        x: 0,
        y: 400,
        vx: 0,
        vy: 0,
        onGround: true,
        wasOnGround: true,
        supportId: "upper_green",
        dropThroughTimer: 0,
        ordinaryJumpActive: false
    });
    stepSimulation(state, createInputFrame({ dropPressed: true, dropHeld: true }), FIXED_DT);
    assert.ok(state.player.currentTransform.y > 400, "pressing down while standing on a green line should begin falling through it immediately");
    assert.equal(state.player.onGround, false, "the green line should release the player while drop-through is active");
    stepMany(state, 45);
    approx(state.player.currentTransform.y, 600, 0.001, "a player dropping through green should land on the yellow floor below");
    assert.equal(state.player.supportId, "lower_yellow", "yellow geometry below a drop-through should remain a normal landing support");

    Object.assign(state.player, {
        x: 0,
        y: 380,
        vx: 0,
        vy: 160,
        onGround: false,
        wasOnGround: false,
        supportId: null,
        dropThroughTimer: 0,
        ordinaryJumpActive: false
    });
    stepSimulation(state, createInputFrame({ dropPressed: true, dropHeld: true }), FIXED_DT);
    stepMany(state, 10);
    assert.ok(state.player.currentTransform.y > 405, "pressing down while already falling should carry the player through the next green line");
    assert.notEqual(state.player.supportId, "upper_green", "a falling drop-through must not land on the green line");
    stepMany(state, 35);
    approx(state.player.currentTransform.y, 600, 0.001, "the falling drop-through should still stop at yellow geometry");

    Object.assign(state.player, {
        x: 0,
        y: 600,
        vx: 0,
        vy: 0,
        onGround: true,
        wasOnGround: true,
        supportId: "lower_yellow",
        dropThroughTimer: 0,
        ordinaryJumpActive: false
    });
    stepMany(state, 30, () => createInputFrame({ dropHeld: true }));
    approx(state.player.currentTransform.y, 600, 0.001, "holding down must never pass through a yellow blocking line");
    assert.equal(state.player.supportId, "lower_yellow", "yellow lines remain authoritative even while drop-through input is held");

    const input = new RocketfrockInput({ addEventListener() {} });
    input.onMouseDown({
        button: 0,
        clientX: 100,
        clientY: 100,
        target: { closest() { return null; } },
        preventDefault() {}
    });
    input.onMouseMove({ clientX: 100, clientY: 155, preventDefault() {} });
    input.onMouseEnd({ preventDefault() {} });
    const swipeFrame = input.sample();
    assert.equal(swipeFrame.dropHeld, true, "a completed downward mouse or touch-style swipe should pulse player drop-through");
    assert.equal(swipeFrame.dropPressed, true, "a fresh downward swipe should create a drop-through press edge even when released before sampling");
    const postSwipeFrame = input.sample();
    assert.equal(postSwipeFrame.dropHeld, false, "the completed swipe pulse should last for only one sampled frame");
    assert.equal(postSwipeFrame.dropReleased, true, "the completed swipe pulse should produce a clean release edge");

    const rightClickInput = new RocketfrockInput({ addEventListener() {} });
    let prevented = false;
    rightClickInput.onMouseDown({
        type: "mousedown",
        button: 2,
        clientX: 120,
        clientY: 90,
        target: { closest() { return null; } },
        preventDefault() { prevented = true; }
    });
    const rightClickFrame = rightClickInput.sample();
    assert.equal(prevented, true, "right-click weapon input should suppress the browser context menu");
    assert.equal(rightClickFrame.weaponPressed, true, "one right click should launch the rocket without requiring a double-click");
    assert.equal(rightClickInput.sample().weaponPressed, false, "right-click weapon input should be a one-frame press pulse");

    const independentButtonsInput = new RocketfrockInput({ addEventListener() {} });
    independentButtonsInput.onMouseDown({
        type: "mousedown",
        button: 0,
        clientX: 100,
        clientY: 100,
        target: { closest() { return null; } },
        preventDefault() {}
    });
    independentButtonsInput.onMouseMove({ clientX: 170, clientY: 100, preventDefault() {} });
    independentButtonsInput.onMouseDown({
        type: "mousedown",
        button: 2,
        clientX: 170,
        clientY: 100,
        target: { closest() { return null; } },
        preventDefault() {}
    });
    const independentButtonsFrame = independentButtonsInput.sample();
    assert.ok(independentButtonsFrame.moveAxis > 0.35, "holding the left mouse button and dragging should continue to steer right");
    assert.equal(independentButtonsFrame.weaponPressed, true, "right click should fire independently while the left mouse button remains held");

    const listeners = new Map();
    const pointerTarget = {
        addEventListener(type, listener) {
            if (!listeners.has(type)) listeners.set(type, []);
            listeners.get(type).push(listener);
        }
    };
    const originalPointerEvent = globalThis.window?.PointerEvent;
    if (!globalThis.window) globalThis.window = {};
    globalThis.window.PointerEvent = class PointerEvent {};
    try {
        const pointerButtonsInput = new RocketfrockInput(pointerTarget);
        const dispatch = (type, event) => {
            for (const listener of listeners.get(type) || []) listener(event);
        };
        dispatch("pointerdown", {
            type: "pointerdown",
            pointerType: "mouse",
            pointerId: 1,
            button: 0,
            clientX: 100,
            clientY: 100,
            target: { closest() { return null; }, setPointerCapture() {} },
            preventDefault() {}
        });
        dispatch("pointermove", {
            type: "pointermove",
            pointerType: "mouse",
            pointerId: 1,
            clientX: 170,
            clientY: 100,
            preventDefault() {}
        });
        dispatch("pointermove", {
            type: "pointermove",
            pointerType: "mouse",
            pointerId: 1,
            button: 2,
            buttons: 3,
            clientX: 170,
            clientY: 100,
            target: { closest() { return null; } },
            preventDefault() {}
        });
        const pointerButtonsFrame = pointerButtonsInput.sample();
        assert.ok(pointerButtonsFrame.moveAxis > 0.35, "Pointer Events should preserve left-button steering while right is pressed");
        assert.equal(pointerButtonsFrame.weaponPressed, true, "the additional right-button transition reported as pointermove should fire while left remains held");
    } finally {
        if (originalPointerEvent === undefined) delete globalThis.window.PointerEvent;
        else globalThis.window.PointerEvent = originalPointerEvent;
    }

    const multiTouchInput = new RocketfrockInput({ addEventListener() {} });
    const touchTarget = { closest() { return null; } };
    const touchEvent = (type, changedTouches) => ({
        type,
        changedTouches,
        target: touchTarget,
        preventDefault() {}
    });
    multiTouchInput.onTouchStart(touchEvent("touchstart", [{ identifier: 1, clientX: 100, clientY: 100 }]));
    multiTouchInput.onTouchMove(touchEvent("touchmove", [{ identifier: 1, clientX: 180, clientY: 100 }]));
    multiTouchInput.onTouchStart(touchEvent("touchstart", [{ identifier: 2, clientX: 400, clientY: 300 }]));
    assert.equal(multiTouchInput.pointer.activeTouchId, "touch:1", "a second finger must not steal virtual-stick ownership");
    multiTouchInput.onTouchEnd(touchEvent("touchend", [{ identifier: 2, clientX: 400, clientY: 300 }]));
    assert.equal(multiTouchInput.pointer.active, true, "releasing a non-owning second finger must not end the active virtual stick");
    assert.ok(multiTouchInput.sample().moveAxis > 0.35, "the original touch should continue steering after a second finger is released");
    multiTouchInput.onTouchEnd(touchEvent("touchend", [{ identifier: 1, clientX: 180, clientY: 100 }]));
    assert.equal(multiTouchInput.pointer.active, false, "releasing the owning finger should end the virtual stick normally");
}


function testGroundEnemyAutomaticSmallStep() {
    const createEnemyStepState = (stepHeight) => {
        const state = createCatalogBackedGameState();
        assert.equal(applyEditorLevelToWorld(state, {
            levelId: `enemy_small_step_${stepHeight}`,
            testPlayerStart: { x: -1000, y: 600 },
            entities: [{
                id: "step_enemy",
                type: "characterEnemy",
                characterId: "ct_char_enemy_001",
                x: 100,
                y: 600,
                w: 72,
                h: 150,
                facing: 1,
                strategy: "simple_patrol",
                patrolDistance: 400,
                walkSpeed: 60,
                idleDuration: 0,
                turnPause: 0,
                maxStepHeight: 0,
                maxDropDistance: 100,
                awarenessRange: 10,
                renderScale: 0.8,
                targetAnchor: { x: 0.5, y: 0.4 }
            }]
        }), true, "enemy small-step fixture should apply");
        state.world.solids = [
            { id: "enemy_step_floor", kind: "floor", x: -1000, y: 600, w: 2000, h: 200 },
            { id: "enemy_small_step", kind: "solid", x: 150, y: 600 - stepHeight, w: 400, h: 200 + stepHeight }
        ];
        state.world.segments = [];
        state.world.collisionPolygons = [];
        state.story.portalIntro = null;
        state.story.portalExit = null;
        state.story.mailboxEvent = null;
        return state;
    };

    const climbable = createEnemyStepState(29);
    stepMany(climbable, 100);
    const climbingEnemy = climbable.enemies.find((enemy) => enemy.id === "step_enemy");
    assert.ok(climbingEnemy.currentTransform.x > 150, "a grounded monster should walk over a step below one fifth of its height");
    assert.equal(climbingEnemy.currentTransform.y, 571, "the grounded monster should follow the raised support without a jump state");

    const tooTall = createEnemyStepState(31);
    stepMany(tooTall, 100);
    const blockedEnemy = tooTall.enemies.find((enemy) => enemy.id === "step_enemy");
    assert.equal(blockedEnemy.currentTransform.y, 600, "a monster should not climb a step above one fifth of its height");
    assert.equal(blockedEnemy.facing, -1, "a simple patrol monster should turn around at a genuinely blocking step");
}

function testCharacterEnemyRuntimeLoaderMatchesSdlSemantics() {
    const state = createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, {
        levelId: "enemy_runtime_loader_parity_test",
        testPlayerStart: { x: 0, y: 600 },
        entities: [{
            id: "loader_parity_enemy",
            type: "characterEnemy",
            characterId: "ct_missing_loader_parity",
            x: 100,
            y: 600,
            spawnX: 42,
            spawnY: 580,
            strategy: "Hunter",
            locomotion: "Flying",
            runSpeed: 60,
            projectileKnockbackX: -7,
            projectileVisualScale: 0.02,
            projectileExplosionVisualScale: 0.02,
            spreadAngle: 270,
            projectileOriginLocalX: null,
            projectileOriginLocalY: null
        }]
    }), true, "loader parity fixture should apply");
    const enemy = state.enemies.find((item) => item.id === "loader_parity_enemy");
    assert.equal(enemy.strategy, "Hunter", "SDL parity: strategy strings are preserved verbatim instead of lowercased/validated");
    assert.equal(enemy.locomotion, "ground", "SDL parity: only the exact authored string 'flying' selects flying locomotion");
    assert.equal(enemy.spawnX, 42, "SDL parity: authored spawnX overrides the live x position for the home point");
    assert.equal(enemy.spawnY, 580, "SDL parity: authored spawnY overrides the live y position for the home point");
    assert.equal(enemy.bomberHorizontalSpeed, 150, "SDL parity: missing bomber speed defaults to at least 150 even when runSpeed is lower");
    assert.equal(enemy.projectileKnockbackX, -7, "SDL parity: authored horizontal projectile knockback is not clamped nonnegative at load time");
    assert.equal(enemy.projectileVisualScale, 0.02, "SDL parity: projectile visual scale clamps at 0.01 rather than 0.05");
    assert.equal(enemy.projectileExplosionVisualScale, 0.02, "SDL parity: projectile explosion scale clamps at 0.01 rather than 0.05");
    assert.equal(enemy.projectileVolleyHalfAngle, 270, "SDL parity: authored volley half-angle is only clamped at zero during runtime loading");
    assert.equal(enemy.hasProjectileOriginLocal, false, "SDL parity: explicit null projectile origin coordinates are not treated as valid zeroes");

    enemy.locomotion = "flying";
    enemy.strategy = "sentry";
    enemy.runSpeed = 60;
    enemy.bomberHorizontalSpeed = 0;
    enemy.panicTimer = 1;
    enemy.panicPhase = "move";
    enemy.panicPhaseTimer = 1;
    enemy.panicMoveDirection = 1;
    const panicStartX = enemy.currentTransform.x;
    stepSimulation(state, createInputFrame(), FIXED_DT);
    approx(enemy.currentTransform.x - panicStartX, 120 * FIXED_DT, 0.000001, "SDL parity: flying panic falls back to max(120, runSpeed) when bomber speed is zero");
}

