function testBufferedGameplayEdgesSurviveRenderOnlyFrames() {
    const keyEvent = (code) => ({
        code,
        repeat: false,
        preventDefault() {}
    });

    const input = new RocketfrockInput({ addEventListener() {} });
    input.onKeyDown(keyEvent("KeyW"));
    const firstRenderOnlySample = input.sample({ consumeGameplayEdges: false });
    assert.equal(firstRenderOnlySample.jumpPressed, true, "a jump press should be visible immediately");
    assert.equal(firstRenderOnlySample.jumpHeld, true, "the held jump state should accompany the buffered edge");

    const secondRenderOnlySample = input.sample({ consumeGameplayEdges: false });
    assert.equal(secondRenderOnlySample.jumpPressed, true, "a render frame with no simulation step must not consume the jump edge");
    input.consumeGameplayEdges(secondRenderOnlySample);

    const heldAfterConsumption = input.sample({ consumeGameplayEdges: false });
    assert.equal(heldAfterConsumption.jumpPressed, false, "the first fixed step should consume the buffered press exactly once");
    assert.equal(heldAfterConsumption.jumpHeld, true, "consuming an edge must not clear the physical held state");

    input.onKeyUp(keyEvent("KeyW"));
    input.onKeyDown(keyEvent("KeyW"));
    const releaseAndRepress = input.sample({ consumeGameplayEdges: false });
    assert.equal(releaseAndRepress.jumpReleased, true, "a release between samples should remain buffered");
    assert.equal(releaseAndRepress.jumpPressed, true, "a repress between samples should remain buffered alongside the release");
    assert.equal(releaseAndRepress.jumpHeld, true, "release plus repress should finish in the held state");
    input.consumeGameplayEdges(releaseAndRepress);
    const cleanHeldFrame = input.sample({ consumeGameplayEdges: false });
    assert.equal(cleanHeldFrame.jumpPressed, false, "the buffered repress should not repeat after consumption");
    assert.equal(cleanHeldFrame.jumpReleased, false, "the buffered release should not repeat after consumption");

    const completeTap = new RocketfrockInput({ addEventListener() {} });
    completeTap.onKeyDown(keyEvent("KeyW"));
    completeTap.onKeyUp(keyEvent("KeyW"));
    const tapFrame = completeTap.sample({ consumeGameplayEdges: false });
    assert.equal(tapFrame.jumpPressed, true, "a complete tap between samples should preserve its press edge");
    assert.equal(tapFrame.jumpReleased, true, "a complete tap between samples should preserve its release edge");
    assert.equal(tapFrame.jumpHeld, false, "a complete tap should finish released");

    const state = createInitialGameState();
    settleOnGround(state);
    const gameplayInput = new RocketfrockInput({ addEventListener() {} });
    gameplayInput.onKeyDown(keyEvent("KeyW"));
    const groundJump = gameplayInput.sample({ consumeGameplayEdges: false });
    stepSimulation(state, groundJump, FIXED_DT);
    gameplayInput.consumeGameplayEdges(groundJump);
    assert.equal(state.player.onGround, false, "the buffered ground press should start the ordinary jump");

    gameplayInput.onKeyUp(keyEvent("KeyW"));
    gameplayInput.onKeyDown(keyEvent("KeyW"));
    const doubleJump = gameplayInput.sample({ consumeGameplayEdges: false });
    stepSimulation(state, doubleJump, FIXED_DT);
    gameplayInput.consumeGameplayEdges(doubleJump);
    assert.equal(state.equipment.rocket.attachedBoosting, true, "a release and repress between fixed steps should arm and start the air boost");
    const boostStarts = state.debug.lastEvents.filter((event) => event.type === "PLAYER_BOOST_STARTED").length;
    assert.equal(boostStarts, 1, "the buffered double-jump gesture should start exactly one boost");

    const sustain = gameplayInput.sample({ consumeGameplayEdges: false });
    stepSimulation(state, sustain, FIXED_DT);
    gameplayInput.consumeGameplayEdges(sustain);
    assert.equal(
        state.debug.lastEvents.filter((event) => event.type === "PLAYER_BOOST_STARTED").length,
        boostStarts,
        "holding jump after edge consumption must not retrigger the air boost"
    );

    const bootstrapSource = readFileSync("./src/browser/game-bootstrap.js", "utf8");
    assert.match(bootstrapSource, /input\.sample\(\{ consumeGameplayEdges: false \}\)/, "the browser loop should sample without consuming gameplay edges");
    assert.match(bootstrapSource, /while \([^\n]*accumulator >= FIXED_DT[\s\S]*stepSimulation\(gameState, stepInput, FIXED_DT\);[\s\S]*input\.consumeGameplayEdges\(stepInput\)/, "the browser loop should consume gameplay edges only after the first fixed step runs");
}

function testControlKeysLaunchWeapon() {
    const target = {
        addEventListener() {}
    };
    const input = new RocketfrockInput(target);

    for (const code of ["ControlLeft", "ControlRight"]) {
        let prevented = false;
        input.onKeyDown({
            code,
            repeat: false,
            preventDefault() {
                prevented = true;
            }
        });
        const pressed = input.sample();
        assert.equal(prevented, true, `${code} should suppress the browser's default shortcut handling`);
        assert.equal(pressed.weaponHeld, true, `${code} should hold the weapon input`);
        assert.equal(pressed.weaponPressed, true, `${code} should produce a fresh weapon press`);
        assert.equal(pressed.moveLeft, false, `${code} should not move left`);
        assert.equal(pressed.moveRight, false, `${code} should not move right`);

        input.onKeyUp({
            code,
            repeat: false,
            preventDefault() {}
        });
        const released = input.sample();
        assert.equal(released.weaponHeld, false, `${code} release should clear the weapon input`);
        assert.equal(released.weaponReleased, true, `${code} should produce a weapon release`);
    }
}

function testGamepadTriggersLaunchWeapon() {
    const originalNavigator = Object.getOwnPropertyDescriptor(globalThis, "navigator");
    const buttons = Array.from({ length: 16 }, () => ({ pressed: false, value: 0 }));
    Object.defineProperty(globalThis, "navigator", {
        configurable: true,
        value: {
            getGamepads() {
                return [{ index: 0, axes: [0, 0], buttons }];
            }
        }
    });

    try {
        const input = new RocketfrockInput({ addEventListener() {} });
        buttons[6] = { pressed: false, value: 0.65 };
        const leftTrigger = input.sample();
        assert.equal(leftTrigger.weaponHeld, true, "the left analog gamepad trigger should hold fire");
        assert.equal(leftTrigger.weaponPressed, true, "the left analog gamepad trigger should create a fresh fire edge");
        buttons[6] = { pressed: false, value: 0 };
        const leftRelease = input.sample();
        assert.equal(leftRelease.weaponReleased, true, "releasing the left trigger should release fire");

        buttons[7] = { pressed: true, value: 1 };
        const rightTrigger = input.sample();
        assert.equal(rightTrigger.weaponHeld, true, "the right gamepad trigger should hold fire");
        assert.equal(rightTrigger.weaponPressed, true, "the right gamepad trigger should create a fresh fire edge");
        buttons[7] = { pressed: false, value: 0 };
        const rightRelease = input.sample();
        assert.equal(rightRelease.weaponReleased, true, "releasing the right trigger should release fire");
    } finally {
        if (originalNavigator) {
            Object.defineProperty(globalThis, "navigator", originalNavigator);
        } else {
            delete globalThis.navigator;
        }
    }
}

function testRemappableGameplayBindings() {
    let bindings = assignInputBinding(DEFAULT_INPUT_BINDINGS, "upLeft", "keyboard:KeyQ");
    bindings = assignInputBinding(bindings, "pause", "keyboard:KeyP");
    const input = new RocketfrockInput({ addEventListener() {} }, bindings);

    input.onKeyDown({ code: "KeyQ", repeat: false, preventDefault() {} });
    const diagonal = input.sample();
    assert.equal(diagonal.jumpHeld, true, "an advanced Up + Left binding should hold jump");
    assert.equal(diagonal.moveLeft, true, "an advanced Up + Left binding should hold left movement");
    assert.equal(diagonal.moveRight, false, "an advanced Up + Left binding should not hold right movement");
    input.onKeyUp({ code: "KeyQ", repeat: false, preventDefault() {} });
    input.sample();

    input.onKeyDown({ code: "KeyP", repeat: false, preventDefault() {} });
    const pause = input.sample();
    assert.equal(pause.pausePressed, true, "a user-mapped Pause key should produce the pause edge");
    assert.equal(pause.debugPausePressed, false, "mapping a development shortcut key should suppress its hidden debug action");
    input.onKeyUp({ code: "KeyP", repeat: false, preventDefault() {} });
    input.sample();

    const multi = new RocketfrockInput({ addEventListener() {} }, DEFAULT_INPUT_BINDINGS);
    multi.onKeyDown({ code: "KeyW", repeat: false, preventDefault() {} });
    assert.equal(multi.sample().jumpPressed, true, "the first held binding for an action should produce its press edge");
    multi.onKeyDown({ code: "ArrowUp", repeat: false, preventDefault() {} });
    assert.equal(multi.sample().jumpPressed, false, "pressing a second binding for an already-held action should not produce another press edge");
    multi.onKeyUp({ code: "KeyW", repeat: false, preventDefault() {} });
    const oneStillHeld = multi.sample();
    assert.equal(oneStillHeld.jumpHeld, true, "an action should remain held while any of its bindings remains held");
    assert.equal(oneStillHeld.jumpReleased, false, "releasing one of several held bindings should not release the action");
    multi.onKeyUp({ code: "ArrowUp", repeat: false, preventDefault() {} });
    assert.equal(multi.sample().jumpReleased, true, "releasing the final held binding should release the action");

    const captureLeak = new RocketfrockInput({ addEventListener() {} }, DEFAULT_INPUT_BINDINGS);
    captureLeak.onKeyDown({ code: "KeyP", repeat: false, preventDefault() {} });
    captureLeak.setInputBindings(assignInputBinding(DEFAULT_INPUT_BINDINGS, "pause", "keyboard:KeyP"));
    captureLeak.clear();
    const clearedAfterCapture = captureLeak.sample();
    assert.equal(clearedAfterCapture.pausePressed, false, "clearing input after binding capture should discard the remapped Pause pulse");
    assert.equal(clearedAfterCapture.debugPausePressed, false, "clearing input after binding capture should discard development hotkeys queued before the new mapping existed");
    assert.equal(captureLeak.takeBindingPress(), "", "clearing input after binding capture should discard queued capture tokens");
}


function testAttachedSmokeDownSpeedTuning() {
    const state = createInitialGameState({
        tuning: {
            attachedBoostSmokePuffDownSpeed: 260,
            attachedBoostSmokePuffSideSpeed: 20,
            attachedBoostSmokePuffSpeedJitter: 0
        }
    });
    settleOnGround(state);
    stepSimulation(state, createInputFrame({ jumpPressed: true, jumpHeld: true }), FIXED_DT);
    releaseJumpAfterTakeoff(state);
    stepMany(state, 3, () => createInputFrame({ jumpHeld: false }));
    stepSimulation(state, createInputFrame({ jumpPressed: true, jumpHeld: true }), FIXED_DT);
    const attachedPuffs = state.effects.smokePuffs.filter((puff) => puff.kind === "attachedRocketSmokePuff");
    assert.ok(attachedPuffs.length >= 4, "expected attached boost smoke puffs");
    const maxVy = Math.max(...attachedPuffs.map((puff) => puff.vy));
    assert.ok(maxVy >= 210, `expected smoke down speed tuning to affect vy, got ${maxVy}`);

    const originState = createInitialGameState({
        tuning: {
            attachedBoostSmokePuffDownSpeed: 0,
            attachedBoostSmokePuffSideSpeed: 0,
            attachedBoostSmokePuffSpeedJitter: 0
        }
    });
    settleOnGround(originState);
    stepSimulation(originState, createInputFrame({ jumpPressed: true, jumpHeld: true }), FIXED_DT);
    releaseJumpAfterTakeoff(originState);
    stepMany(originState, 3, () => createInputFrame({ jumpHeld: false }));
    const emissionPlayerY = originState.player.currentTransform.y;
    stepSimulation(originState, createInputFrame({ jumpPressed: true, jumpHeld: true }), FIXED_DT);
    const originPuff = originState.effects.smokePuffs.find((puff) => puff.kind === "attachedRocketSmokePuff");
    assert.ok(originPuff, "expected an attached boost puff for the nozzle-origin regression");
    approx(
        originPuff.y,
        emissionPlayerY - originState.player.height * 0.30 - 2,
        0.001,
        "attached smoke should begin ten pixels closer to the mounted rocket nozzle"
    );
}


function createMovingPlatformTestState(movement, entities = [], options = {}) {
    const level = {
        levelId: "moving_platform_test",
        world: { bounds: { x: 0, y: 0, w: 1000, h: 800 } },
        placements: [{
            id: "moving_platform",
            kind: "atlasAsset",
            atlasId: "at_atlas_001",
            assetId: "test_platform",
            x: 100,
            y: 300,
            w: 100,
            h: 20,
            collisionFromManifest: true,
            movement,
            ...(options.placement || {})
        }],
        entities
    };
    const manifest = options.manifest || {
        frames: {
            test_platform: { x: 0, y: 0, w: 100, h: 20 }
        },
        objects: {
            test_platform: {
                nodes: [
                    { id: "left", x: 0, y: 0 },
                    { id: "right", x: 100, y: 0 }
                ],
                lines: [
                    { id: "top", kind: "walkable", from: "left", to: "right", tags: [] }
                ]
            }
        }
    };
    const state = options.state || createInitialGameState();
    assert.equal(applyEditorLevelToWorld(state, level), true, "moving-platform test level should apply");
    assert.equal(
        applyAtlasManifestsToWorld(state, new Map([["at_atlas_001", { manifest }]])),
        true,
        "moving-platform test manifest should create collision"
    );
    return state;
}

function placePlayerOnMovingPlatform(state) {
    const platform = state.world.movingPlatforms[0];
    const supportId = platform.segments[0]?.id;
    assert.ok(supportId, "moving platform should own a walkable support");
    state.player.currentTransform.x = 150;
    state.player.currentTransform.y = 300;
    state.player.spawnX = 150;
    state.player.spawnY = 300;
    state.player.vx = 0;
    state.player.vy = 0;
    state.player.onGround = true;
    state.player.wasOnGround = true;
    state.player.supportId = supportId;
    return platform;
}


